-- SCRIPT_PROD_20261123_COMPETENCIAS_CRITICIDAD_METODO_EVIDENCIA.sql
-- Aplicar por pgAdmin en xlab-extended (BD de DocSafe). Requiere la migracion
-- 20261123_02_rh_position_competency_method_evidence.sql.
--
-- Que hace: carga en el catalogo de competencias de cada puesto la Criticidad, el
-- Metodo y "Que se observa" de la seccion 3 (Evaluacion practica) del REH-REG-003
-- Rev. 2, tomados de los 38 formatos por puesto (451 competencias).
--   Criticidad      -> criticality (A / M / B)
--   Metodo          -> method (clave de SafeDoc; ver mapeo abajo)
--   Que se observa  -> evidence_guide (se precarga en Observaciones / evidencia)
--
-- Mapeo del metodo (si el formato combina dos, se toma el primero):
--   OD Observacion directa: observacion directa, resolucion de casos (incluye
--      "simulaciones operativas o resolucion de casos") y muestras previamente analizadas
--   RR Revision de registro: revision o seguimiento de registros, supervisiones
--      documentadas, verificacion del cumplimiento, indicadores de desempeno
--   SI Simulacion: simulacion operativa
--   EP Examen practico: evaluaciones practicas, capacidad para resolver problemas tecnicos
--   ES Examen escrito: evaluaciones teoricas o escritas
--
-- Empata por codigo de puesto + texto de la competencia (sin acentos, mayusculas ni
-- puntuacion). Lo que no empate sale en el listado "SIN EMPATAR" y no se toca.
-- Que NO hace: no toca evaluaciones existentes (ni borradores ni cerradas); aplica
-- a las evaluaciones que se creen despues. No borra nada. Repetirlo no cambia nada.
-- Compatible con PostgreSQL 10.
BEGIN;

CREATE TEMP TABLE tmp_comp (position_code TEXT, row_no INT, competency_text TEXT, criticality TEXT, method TEXT, evidence_guide TEXT) ON COMMIT DROP;


CREATE FUNCTION pg_temp.norm_comp(t TEXT) RETURNS TEXT AS $$
  SELECT regexp_replace(translate(lower(t), 'áéíóúüñ', 'aeiouun'), '[^a-z0-9]', '', 'g');
$$ LANGUAGE sql IMMUTABLE;

CREATE TEMP TABLE tmp_match ON COMMIT DROP AS
SELECT t.*, c.id AS competency_id,
       (c.criticality IS DISTINCT FROM t.criticality OR c.method IS DISTINCT FROM t.method
        OR c.evidence_guide IS DISTINCT FROM t.evidence_guide) AS cambia
  FROM tmp_comp t
  LEFT JOIN public.rh_positions p ON p.code = t.position_code
  LEFT JOIN public.rh_position_competencies c
         ON c.position_id = p.id AND pg_temp.norm_comp(c.competency_text) = pg_temp.norm_comp(t.competency_text);

UPDATE public.rh_position_competencies c
   SET criticality = m.criticality, method = m.method, evidence_guide = m.evidence_guide
  FROM tmp_match m
 WHERE m.competency_id = c.id AND m.cambia;

-- Listado 1: resumen.
SELECT COUNT(*)::int AS filas_del_formato,
       COUNT(competency_id)::int AS empatadas,
       SUM(CASE WHEN competency_id IS NOT NULL AND cambia THEN 1 ELSE 0 END)::int AS actualizadas,
       SUM(CASE WHEN competency_id IS NULL THEN 1 ELSE 0 END)::int AS sin_empatar
  FROM tmp_match;

-- Listado 2: SIN EMPATAR (no se tocaron; revisar el texto de la competencia en /rh/positions).
SELECT position_code, row_no, competency_text FROM tmp_match WHERE competency_id IS NULL ORDER BY 1, 2;

-- Listado 3: competencias del catalogo que el formato no trae (quedan sin metodo).
SELECT p.code, c.competency_text
  FROM public.rh_position_competencies c JOIN public.rh_positions p ON p.id = c.position_id
 WHERE p.is_active AND c.method IS NULL ORDER BY 1, 2;

COMMIT;
