INSERT INTO tmp_comp VALUES
    ('ALM', 1, 'Recibir e inspeccionar productos contra documentos de compra y criterios establecidos.', 'A', 'OD', 'Recibe una entrega real, la compara contra la orden de compra y la factura o remisión y decide aceptar, rechazar o condicionar.'),
    ('ALM', 2, 'Verificar lote, caducidad, cantidad, presentación, integridad y condiciones de transporte.', 'A', 'OD', 'Revisa lote, caducidad, cantidad, presentación, integridad del empaque y toma la temperatura de transporte al recibir.'),
    ('ALM', 3, 'Controlar inventarios físicos y electrónicos.', 'M', 'RR', 'Realiza un conteo físico, lo compara contra el inventario del sistema y documenta las discrepancias.'),
    ('ALM', 4, 'Aplicar FEFO y PEPS según corresponda.', 'A', 'OD', 'Surte una requisición entregando primero el lote con caducidad más próxima.'),
    ('ALM', 5, 'Mantener la trazabilidad de entradas, salidas, devoluciones y transferencias.', 'A', 'RR', 'Rastrea un lote desde su entrada hasta el área que lo recibió.'),
    ('ALM', 6, 'Controlar productos en cuarentena, rechazados, caducados o retirados.', 'A', 'OD', 'Ante un lote retirado por el proveedor, lo localiza, lo separa e identifica y documenta el incidente.'),
    ('ALM', 7, 'Vigilar y registrar condiciones de temperatura y humedad.', 'A', 'RR', 'Muestra los registros de temperatura y humedad del periodo, completos y dentro de intervalo, o con la desviación atendida.'),
    ('ALM', 8, 'Responder ante desviaciones de almacenamiento y activar controles de contingencia.', 'A', 'OD', 'Ante una falla simulada de un refrigerador, reubica el material, registra la desviación y avisa al coordinador.'),
    ('ALM', 9, 'Interpretar etiquetas, instrucciones de conservación y fichas de datos de seguridad.', 'M', 'OD', 'Lee la etiqueta y la hoja de datos de seguridad de un producto y explica cómo conservarlo y qué riesgos tiene.'),
    ('ALM', 10, 'Segregar sustancias químicas conforme a su compatibilidad y riesgo.', 'M', 'OD', 'Ubica sustancias químicas separando las incompatibles y las inflamables, corrosivas o tóxicas.'),
    ('ALM', 11, 'Calcular existencias mínimas, máximas, consumo y puntos de reorden.', 'M', 'OD', 'Calcula con el consumo de un trimestre el mínimo, máximo y punto de reorden de un reactivo.'),
    ('ALM', 12, 'Preparar y entregar requisiciones con exactitud.', 'M', 'OD', 'Prepara y entrega una requisición sin faltantes ni sobrantes y obtiene la firma de recibido.'),
    ('ALM', 13, 'Manejar hojas de cálculo, sistemas de inventario y herramientas ofimáticas.', 'B', 'EP', 'Opera en XLAB Inventario la entrada, el suministro y la consulta de caducidades.'),
    ('ALM', 14, 'Identificar riesgos, productos no conformes y oportunidades de mejora.', 'M', 'OD', 'Identifica en un caso un producto no conforme o un riesgo de desabasto y lo reporta por la vía correcta.'),
    ('ALM', 15, 'Elaborar reportes de inventario, consumo, caducidades, diferencias y desempeño de proveedores.', 'M', 'RR', 'Entrega un reporte de consumo, caducidades, diferencias y cumplimiento de proveedores del mes.'),
    ('AN-A', 1, 'Interpretación y aplicación de los requisitos de la Norma ISO 15189:2022 y de la documentación vigente del Sistema de Gestión de la Calidad.', 'B', 'OD', 'Identifica el procedimiento vigente aplicable a su actividad (control interno, controles, reactivos, resguardo) y lo consulta en su versión controlada.'),
    ('AN-A', 2, 'Ejecución e interpretación de procedimientos analíticos en una o más disciplinas del laboratorio clínico.', 'A', 'OD', 'Procesa muestras previamente analizadas de su disciplina con el control interno aceptado, y obtiene resultados concordantes.'),
    ('AN-A', 3, 'Aseguramiento de la validez de los resultados mediante la aplicación del Control Interno de la Calidad, la participación en Programas de Evaluación Externa de la Calidad y la ejecución de las actividades establecidas por el laboratorio para el monitoreo del desempeño analítico.', 'A', 'OD', 'Procesa los controles antes de pacientes y una muestra de evaluación externa integrada al flujo rutinario, sin comunicar sus datos a otros participantes.'),
    ('AN-A', 4, 'Revisión, verificación e interpretación de resultados analíticos conforme a los criterios técnicos establecidos por el laboratorio y a los procedimientos institucionales, previo a su validación por el personal autorizado.', 'A', 'RR', 'Anota los resultados en verificación con (*), verifica del tubo primario con el equipo calibrado y marca (*v), y entrega para validación.'),
    ('AN-A', 5, 'Interpretación de gráficas de control, reglas de control estadístico y evaluación del desempeño analítico.', 'A', 'OD', 'En gráficos de Levey-Jennings del área identifica violaciones de 13s, 22s, R4s y 41s, y explica que no se elimina el dato rechazado.'),
    ('AN-A', 6, 'Operación, verificación y mantenimiento de primer nivel de equipos e instrumentos analíticos.', 'M', 'OD', 'Realiza y registra el mantenimiento diario del equipo asignado y su limpieza, y ante una alarma detiene su uso e informa.'),
    ('AN-A', 7, 'Manejo de reactivos, calibradores, materiales de referencia y controles de calidad conforme a las especificaciones técnicas aplicables.', 'A', 'OD', 'Reconstituye un control con pipeta volumétrica clase A sin expulsar el remanente, rotula alícuotas con los datos requeridos y lo procesa dentro de 5 minutos.'),
    ('AN-A', 8, 'Identificación, documentación y gestión de trabajos no conformes, desviaciones e incidentes relacionados con el proceso analítico.', 'A', 'OD', 'Ante un caso de reactivo caducado en uso, detiene, comunica y documenta el evento con su fuente de detección y acciones inmediatas.'),
    ('AN-A', 9, 'Aplicación de los principios de trazabilidad metrológica y participación en actividades de incertidumbre de medición y verificación o validación de métodos, cuando sean aplicables a su área de trabajo y conforme a los procedimientos institucionales.', 'M', 'RR', 'Explica de dónde sale cada componente del error cuadrático medio de un analito de su área y localiza su carta de trazabilidad.'),
    ('AN-A', 10, 'Manejo del Sistema Informático de Laboratorio (SIL/LIS), sistemas institucionales y registros electrónicos aplicables.', 'M', 'OD', 'Registra resultados en el sistema autorizado y elabora en XLAB INVENTARIO un vale de salida.'),
    ('AN-A', 11, 'Aplicación de medidas de bioseguridad, seguridad e higiene durante el proceso analítico.', 'M', 'OD', 'Manipula controles y muestras con guantes, bata y lentes, como lo exige el instructivo de controles.'),
    ('AN-A', 12, 'Gestión documental, control de registros y aseguramiento de la trazabilidad de la información generada durante el proceso analítico.', 'M', 'RR', 'Sus registros de temperatura, condiciones ambientales y bitácora están completos, legibles y oportunos.'),
    ('AN-A', 13, 'Identificación, evaluación y control de riesgos asociados al proceso analítico conforme a los procedimientos institucionales.', 'B', 'OD', 'Identifica en un caso de desabasto o falla de equipo el riesgo para el paciente y lo comunica al Analista "B" o Responsable del Área para su registro.'),
    ('AN-A', 14, 'Interpretación de especificaciones técnicas, instructivos de fabricantes y documentación científica relacionada con las metodologías analíticas bajo su responsabilidad.', 'M', 'OD', 'Con el procedimiento de examen de un analito, localiza estabilidad del reactivo a bordo, frecuencia de calibración, intervalo reportable y conducta ante resultados fuera del intervalo.'),
    ('AN-B', 1, 'Interpretación y aplicación de los procedimientos del Sistema de Gestión de la Calidad y de los requisitos aplicables de la norma ISO 15189:2022.', 'M', 'OD', 'Explica qué procedimiento de UNILABOR aplica a un caso del área (control fuera de criterio, reactivo no conforme, falla de equipo) y qué registro llena.'),
    ('AN-B', 2, 'Procesamiento analítico de muestras biológicas conforme a los procedimientos establecidos.', 'A', 'OD', 'Procesa en el analizador muestras ya analizadas, con el control interno validado previamente, y sus resultados concuerdan con los originales.'),
    ('AN-B', 3, 'Operación, verificación operativa y cuidado de los equipos analíticos autorizados para su puesto.', 'A', 'OD', 'Ejecuta y registra el mantenimiento diario del analizador asignado y la limpieza y desinfección del equipo, y verifica su estado antes de procesar.'),
    ('AN-B', 4, 'Aplicación e interpretación del control de calidad interno y participación en Programas de Evaluación Externa de la Calidad, cuando aplique.', 'A', 'OD', 'Procesa los controles antes de pacientes, transmite a Unity Real Time, interpreta Levey-Jennings con las reglas asignadas, y procesa y captura una muestra PACAL como muestra de paciente dentro del plazo.'),
    ('AN-B', 5, 'Validación técnica de resultados conforme a las actividades y autorizaciones asignadas.', 'A', 'RR', 'En AMS envía a verificación los resultados que cumplen los criterios (antecedente, diferencia mayor de 20 % en inmunoquímica), valida solo si el reproceso no excede 5 % y marca (*V) y (LIB) en la bitácora.'),
    ('AN-B', 6, 'Aplicación de los criterios de aceptación y rechazo de muestras.', 'A', 'OD', 'Ante muestras con identificación incompleta o ilegible, no las procesa y lo notifica; ante muestras con desviaciones registradas en recepción, las anota en observaciones del informe.'),
    ('AN-B', 7, 'Gestión documental, control de registros y trazabilidad de muestras, resultados e información.', 'M', 'RR', 'Las bitácoras del analista y de prioritarios y urgentes están completas al cierre, sin muestras pendientes y con la trazabilidad de diluciones o tubo primario.'),
    ('AN-B', 8, 'Identificación y notificación de desviaciones, incidentes, riesgos y trabajos no conformes conforme al Sistema de Gestión de la Calidad.', 'A', 'OD', 'Ante un caso, detiene la actividad sin esperar autorización, comunica al coordinador e inicia el registro del evento en ese momento.'),
    ('AN-B', 9, 'Manejo de los sistemas informáticos del laboratorio (LIS, XLAB u otros autorizados).', 'M', 'OD', 'Imprime de X-Lab las bitácoras del área, elabora la solicitud de pedido en XLAB Inventario y libera en AMS dentro de su alcance.'),
    ('AN-C', 1, 'Ejecución autónoma de procedimientos analíticos en múltiples disciplinas.', 'A', 'OD', 'Procesa muestras ya analizadas de al menos dos disciplinas autorizadas, previa validación del control interno, y obtiene resultados concordantes con los originales.'),
    ('AN-C', 2, 'Validación y liberación de resultados como personal signatario.', 'A', 'OD', 'Ejecuta la Revisión 1 y la Revisión 2 del informe contra la bitácora, corrige transcripciones por la vía establecida y firma solo dentro de su alcance de autorización.'),
    ('AN-C', 3, 'Supervisión técnica y entrenamiento de personal analista.', 'M', 'RR', 'Aplica la lista de verificación de supervisión a un analista de menor categoría, calcula el porcentaje de cumplimiento y clasifica el resultado.'),
    ('AN-C', 4, 'Resolución de desviaciones técnicas durante el proceso de examen.', 'A', 'SI', 'Ante una falla simulada de equipo, detiene su uso, lo identifica como fuera de servicio, registra el incidente y evalúa si hubo trabajo no conforme.'),
    ('AN-C', 5, 'Aplicación e interpretación del control estadístico de la calidad (reglas de Westgard, gráficos de Levey-Jennings).', 'A', 'OD', 'Ante una serie de gráficos de Levey-Jennings del área, identifica la regla violada según las reglas asignadas por sigma, contiene el error interrumpiendo pacientes, no elimina el punto rechazado y define qué pacientes reanalizar desde el último evento en control.'),
    ('AN-C', 6, 'Validación técnica y liberación de resultados.', 'A', 'RR', 'En bitácoras recientes del colaborador, comprueba que los resultados en verificación llevan (*) y (*v), que los liberados llevan (LIB) con iniciales, y que la diferencia entre primer resultado y reproceso no excedió el 5 %.'),
    ('AN-C', 7, 'Verificación del desempeño de métodos y equipos analíticos.', 'A', 'RR', 'Explica y revisa un estudio de verificación del área: réplicas de precisión, criterio de 0,25 o 0,33 del error total, linealidad con puntos de decisión clínica, y la acción cuando un criterio no se cumple.'),
    ('AN-C', 8, 'Trazabilidad metrológica y manejo de materiales de referencia.', 'M', 'RR', 'Localiza la carta de trazabilidad de un analito del alcance, identifica el material de referencia de mayor orden y su incertidumbre, y explica cuándo es aceptable la trazabilidad declarada por el fabricante.'),
    ('AN-C', 9, 'Investigación de desviaciones, trabajo no conforme y análisis de causa raíz.', 'A', 'OD', 'Sobre un caso de control fuera de criterio, aplica detener y retener, determina el alcance desde el último punto bajo control, gradúa el significado clínico, documenta el evento y enlaza la causa raíz por folio.'),
    ('AN-C', 10, 'Gestión documental y control de registros.', 'M', 'RR', 'Verifica que los registros del área que llena el colaborador estén completos, legibles y trazables, en su versión vigente, y que las correcciones conservan el dato original.'),
    ('AN-C', 11, 'Gestión de riesgos aplicada al proceso analítico.', 'M', 'OD', 'Ubica en la matriz los riesgos del área a su cargo y explica los controles vigentes, y propone el registro de un riesgo nuevo detectado en un caso de falla de equipo o desabasto.'),
    ('AN-C', 12, 'Manejo del sistema de información del laboratorio.', 'M', 'OD', 'Ejecuta en X-Lab y AMS la revisión de resultados, el envío a verificación (reanálisis) y la liberación por analito o por paciente, con su usuario y contraseña.'),
    ('ASDM', 1, 'Verificación de idoneidad de muestras primarias.', 'A', 'OD', 'Revisa identificación, tipo de muestra, volumen, conservación, contenedor e interferencias visibles, y marca la Verificación en el sistema XLAB Plus de separación y distribución sólo si la muestra cumple.'),
    ('ASDM', 2, 'Aplicación de criterios de aceptación y rechazo.', 'A', 'OD', 'Clasifica casos (coágulo en EDTA, lipemia severa, tubo fisurado, transporte excedido) en rechazo total, parcial o condicionado según el cuadro, con la acción correspondiente.'),
    ('ASDM', 3, 'Operación segura y verificación de centrífugas.', 'A', 'OD', 'Respeta el tiempo de coagulación, balancea, aplica el programa por tipo de tubo, no abre con el rotor en movimiento y suspende el equipo ante falla o vibración.'),
    ('ASDM', 4, 'Alicuotado e identificación de muestras derivadas.', 'A', 'OD', 'Usa tubo rohen limpio y seco en gradilla exclusiva, coteja el código de barras del tubo primario con el Recibo y etiqueta cada alícuota con la etiqueta del sistema.'),
    ('ASDM', 5, 'Control de condiciones de conservación y cadena de frío.', 'A', 'RR', 'Verifica y registra diariamente las temperaturas de refrigeradores y congeladores del área y separa en la gradilla de condiciones especiales lo que requiere refrigeración o protección de la luz.'),
    ('ASDM', 6, 'Registro y trazabilidad de muestras en el sistema informático.', 'A', 'OD', 'Ordena por folio, distribuye por área y equipo en la gradilla que corresponde y deja constancia de la recepción de muestras de sucursales.'),
    ('ASDM', 7, 'Documentación de trabajo no conforme.', 'M', 'RR', 'El registro de cada rechazo contiene fecha y hora, folio, tipo de desviación, criterio, quien detecta, evaluación, acción y notificación.'),
    ('ASDM', 8, 'Aplicación de medidas de bioseguridad.', 'M', 'OD', 'Usa bata, guantes, cubrebocas y lentes en el área preanalítica y dispensa lento sobre la pared del tubo para evitar aerosoles.'),
    ('AP', 1, 'Atención y orientación a pacientes y usuarios.', 'M', 'OD', 'Aplica la secuencia de atención (saludo, identificar necesidades, comprensión mutua, información, siguientes pasos, despedida).'),
    ('AP', 2, 'Manejo de conmutador telefónico y canales de comunicación institucional.', 'M', 'OD', 'En llamadas simuladas usa las frases obligatorias de llamada externa e interna, transfiere identificando al área y toma mensaje con número de contacto.'),
    ('AP', 3, 'Uso de sistemas informáticos, correo electrónico y plataformas autorizadas por el laboratorio.', 'M', 'OD', 'En una cotización telefónica registra en COMUNICACIÓN el medio de contacto, guarda, reitera el folio y verifica el PDF de la cotización.'),
    ('AP', 4, 'Confidencialidad de la información y protección de datos personales.', 'A', 'OD', 'Verifica la identidad de quien llama antes de dar información de un paciente y no comenta datos sensibles por teléfono.'),
    ('AP', 5, 'Gestión y seguimiento de solicitudes, quejas, sugerencias e incidencias.', 'M', 'OD', 'Ante una queja telefónica la documenta textual en el reporte y la entrega al Coordinador del SGC el mismo día.'),
    ('AP', 6, 'Política, objetivos de calidad y requisitos aplicables del Sistema de Gestión de Calidad.', 'B', 'RR', 'Explica al usuario cómo presentar una queja y que la descripción del proceso está disponible en recepción y en la página de internet.'),
    ('AP', 7, 'Manejo básico de XLAB y sistemas institucionales aplicables al puesto.', 'M', 'OD', 'Al cotizar revisa y edita las indicaciones que el sistema generaliza cuando la combinación de estudios lo requiere (por ejemplo, cultivo uretral con examen general de orina).'),
    ('AUXA', 1, 'Preparación de materiales, reactivos y soluciones.', 'M', 'OD', 'Prepara una solución, colorante o reactivo conforme al procedimiento y a las instrucciones del fabricante, y lo etiqueta con lote, fecha de preparación y caducidad.'),
    ('AUXA', 2, 'Manejo e identificación de muestras biológicas.', 'A', 'OD', 'Coteja las muestras contra la bitácora, las acomoda en el orden de proceso, y no utiliza ni recupera muestras con identificación incompleta o ilegible, notificándolo.'),
    ('AUXA', 3, 'Limpieza, desinfección y mantenimiento de primer nivel de equipos.', 'M', 'OD', 'Realiza la limpieza y desinfección de superficies al inicio y término del turno y la de los equipos asignados, y lo registra.'),
    ('AUXA', 4, 'Verificación y registro de condiciones de conservación.', 'A', 'RR', 'Registra diariamente las temperaturas de refrigeradores (2 a 8 °C) y congeladores (-10 a -20 °C) y reporta cualquier lectura fuera de límites.'),
    ('AUXA', 5, 'Control de caducidades e inventario de insumos.', 'M', 'OD', 'Acomoda insumos por primeras caducidades primeras salidas, separa lo aceptado de lo no inspeccionado, retira lo caducado y apoya la solicitud de pedido en XLAB Inventario.'),
    ('AUXA', 6, 'Aplicación de medidas de bioseguridad y manejo de RPBI.', 'M', 'OD', 'Separa, envasa y dispone los RPBI del área y registra su recolección.'),
    ('AUXA', 7, 'Registro completo y oportuno de bitácoras.', 'M', 'RR', 'Las bitácoras y formatos que llena (temperaturas, limpieza, inventario) están completos, legibles y al día.'),
    ('ACEN', 1, 'Recepción y verificación de muestras.', 'A', 'OD', 'Recibe las muestras de toma o recepción y verifica que las de suero estén coaguladas y que los tubos no tengan derrames ni fisuras antes de cargarlas.'),
    ('ACEN', 2, 'Aplicación de criterios de aceptación y rechazo.', 'A', 'OD', 'Ante un tubo sin identificación, ilegible o con datos discrepantes, lo retiene y lo pasa al Analista de Separación para su evaluación y registro, sin centrifugarlo como si fuera válido.'),
    ('ACEN', 3, 'Operación segura de centrífugas.', 'A', 'OD', 'No abre con el rotor en movimiento, espera el paro completo, revisa derrames y suspende el equipo ante falla o vibración.'),
    ('ACEN', 4, 'Balanceo y distribución adecuada de muestras.', 'A', 'OD', 'Balancea los tubos en el rotor y aplica la fuerza y el tiempo que el cuadro fija para cada tipo de tubo.'),
    ('ACEN', 5, 'Manejo de muestras.', 'M', 'OD', 'Usa la gradilla de muestras sin centrifugar y la de centrifugadas para su propósito y acomoda por folio consecutivo.'),
    ('ACEN', 6, 'Prevención de contaminación cruzada.', 'M', 'OD', 'Limpia y desinfecta la superficie de trabajo y la centrífuga, y mantiene las gradillas limpias y exclusivas para su uso.'),
    ('ACEN', 7, 'Aplicación de medidas de bioseguridad.', 'M', 'OD', 'Porta bata, guantes, cubrebocas y lentes durante la operación de la centrífuga.'),
    ('ACEN', 8, 'Manejo de RPBI.', 'M', 'OD', 'Ante un tubo roto aplica el manejo de derrames y desecha el material conforme al procedimiento de RPBI.'),
    ('ACEN', 9, 'Cumplimiento de procedimientos documentados.', 'M', 'RR', 'Los registros de limpieza de superficie y de centrífuga están completos y al día.'),
    ('ACON', 1, 'Registro y control contable de operaciones.', 'M', 'RR', 'Captura pólizas de ingresos, egresos y diario con su documentación soporte y sin diferencias contra los comprobantes.'),
    ('ACON', 2, 'Verificación de comprobantes fiscales digitales.', 'M', 'EP', 'Valida comprobantes fiscales digitales en el portal correspondiente y rechaza los que no cumplen.'),
    ('ACON', 3, 'Conciliación bancaria y control de caja.', 'M', 'RR', 'Entrega la conciliación bancaria mensual y un arqueo de caja chica con las diferencias explicadas.'),
    ('ACON', 4, 'Cálculo y control de nómina y prestaciones.', 'M', 'OD', 'Calcula un caso de nómina con incidencias, retenciones y aportaciones y lo coteja con Recursos Humanos.'),
    ('ACON', 5, 'Elaboración y seguimiento de órdenes de compra.', 'M', 'OD', 'Genera una orden de compra desde la solicitud registrada en XLAB Inventario y le da seguimiento hasta la entrega.'),
    ('ACON', 6, 'Evaluación y reevaluación de proveedores externos conforme a ISO 15189:2022.', 'A', 'RR', 'Integra el expediente de un proveedor y aplica la evaluación con los criterios documentados.'),
    ('ACON', 7, 'Manejo de hoja de cálculo y sistemas contables.', 'B', 'EP', 'Elabora en hoja de cálculo un reporte de antigüedad de saldos y cuentas por pagar sin errores de fórmula.'),
    ('ACON', 8, 'Control y resguardo de registros conforme al Sistema de Gestión de la Calidad.', 'M', 'RR', 'Archiva y resguarda registros contables con su identificación y aplica las reglas de llenado y corrección.'),
    ('CHOF', 1, 'Uso y manejo adecuado de contenedores y neveras de traslado.', 'A', 'OD', 'Usa una nevera exclusiva para muestras, con refrigerantes suficientes, termómetro visible y símbolo de riesgo biológico, y la desinfecta antes de entrar a cada sede.'),
    ('CHOF', 2, 'Conocimiento y cumplimiento del reglamento de tránsito vigente.', 'M', 'RR', 'Demuestra conocer las disposiciones de seguridad vial que el DPO le exige y mantiene vigente su licencia de conducir.'),
    ('CHOF', 3, 'Manejo y traslado de muestras biológicas conforme a los procedimientos establecidos.', 'A', 'OD', 'Traslada con triple envase, respeta posición del contenedor, protección de la luz y los tiempos que cada análisis admite.'),
    ('CHOF', 4, 'Llenado correcto de bitácoras, registros y formatos de UNILABOR.', 'M', 'RR', 'Registra salidas y recorridos, y en el registro de traslado consigna relación de muestras, origen y destino, horas de salida y llegada, temperaturas y quién entrega y recibe.'),
    ('CHOF', 5, 'Conocimiento básico de bioseguridad, seguridad e higiene.', 'M', 'OD', 'Usa el EPP aplicable, no mezcla muestras con residuos y conoce el contenido del equipo para derrames del vehículo.'),
    ('CHOF', 6, 'Cumplimiento de políticas de confidencialidad y protección de datos.', 'M', 'OD', 'Entrega documentación y resultados sólo al personal autorizado y los resguarda durante el recorrido.'),
    ('CHOF', 7, 'Conducción segura y manejo defensivo.', 'M', 'OD', 'Durante un recorrido supervisado conduce conforme a las disposiciones de seguridad vial y de conducción responsable.'),
    ('CHOF', 8, 'Operación e inspección básica del vehículo.', 'M', 'OD', 'Revisa al inicio las condiciones mecánicas y de seguridad del vehículo y gestiona el mantenimiento cuando hace falta.'),
    ('CHOF', 9, 'Gestión de rutas, logística y puntualidad en entregas.', 'M', 'RR', 'Cumple rutas y horarios de modo que el intervalo entre toma y recepción quede dentro de lo que el catálogo declara para cada análisis.'),
    ('CHOF', 10, 'Atención y respuesta ante emergencias o contingencias.', 'A', 'OD', 'En simulación de derrame en ruta notifica de inmediato al Coordinador de Procedimientos Preanalíticos y al responsable del transporte y usa el equipo para derrames.'),
    ('CHOF', 11, 'Control y resguardo adecuado de los materiales transportados.', 'M', 'OD', 'Al entregar, el número de muestras coincide con el declarado en el registro del traslado y la diferencia, si la hay, se resuelve antes de dar por recibido.'),
    ('CHOF', 12, 'Bioseguridad y transporte seguro de muestras o materiales sensibles (cuando aplique).', 'A', 'OD', 'En envíos de ETDDA mantiene 2 a 8 °C desde la recolección hasta la entrega a Separación y Distribución.'),
    ('CHOF', 13, 'Conservación de trazabilidad, integridad y condiciones de transporte (temperatura, cadena de custodia, estabilidad, etc.).', 'A', 'RR', 'Las temperaturas de inicio y fin se tomaron con un termómetro con verificación vigente y quedan en el registro que acompaña a las muestras.'),
    ('CAF', 1, 'Elaborar y controlar presupuestos, flujo de efectivo y proyecciones financieras.', 'M', 'RR', 'Presenta el presupuesto anual con su control de ejercicio y explica las variaciones contra lo autorizado.'),
    ('CAF', 2, 'Analizar ingresos, egresos, cuentas por cobrar, cuentas por pagar y variaciones presupuestales.', 'M', 'OD', 'Ante un caso con cifras de un mes, identifica ingresos, egresos, cuentas por cobrar y por pagar y señala la variación presupuestal.'),
    ('CAF', 3, 'Revisar conciliaciones bancarias, cortes de caja y registros contables.', 'M', 'RR', 'Revisa una conciliación bancaria y un corte de caja y detecta las diferencias contra el estado de cuenta y el sistema XLAB.'),
    ('CAF', 4, 'Verificar facturas, comprobantes fiscales y documentación soporte.', 'M', 'OD', 'Revisa facturas reales, ratifica los datos fiscales y las coteja contra la orden de compra antes de aceptarlas.'),
    ('CAF', 5, 'Coordinar cálculos y pagos de nómina, prestaciones y obligaciones relacionadas.', 'M', 'RR', 'Revisa con el Coordinador de Recursos Humanos y el despacho contable el cálculo de una nómina y sus prestaciones.'),
    ('CAF', 6, 'Aplicar conocimientos de legislación fiscal, laboral y de seguridad social dentro del alcance del puesto.', 'M', 'OD', 'Resuelve un caso de obligación fiscal, laboral o de seguridad social e indica cuándo escala al asesor externo.'),
    ('CAF', 7, 'Gestionar compras, cotizaciones, órdenes de compra, contratos y pagos a proveedores.', 'A', 'OD', 'Gestiona una compra completa: cotización a proveedor aprobado, orden de compra, seguimiento de entrega y pago.'),
    ('CAF', 8, 'Coordinar la selección, evaluación y seguimiento de proveedores.', 'A', 'RR', 'Muestra la evaluación inicial y la reevaluación de un proveedor y la decisión tomada con base en la calificación.'),
    ('CAF', 9, 'Implementar controles internos y separación de funciones.', 'M', 'RR', 'Demuestra en una compra que solicitud, autorización, compra, recepción y pago los realizan personas distintas.'),
    ('CAF', 10, 'Identificar riesgos financieros, administrativos, de abastecimiento y fraude.', 'M', 'OD', 'Identifica en un caso un riesgo de desabasto o de fraude y propone el control y su registro.'),
    ('CAF', 11, 'Supervisar inventarios, almacén y mantenimiento.', 'M', 'RR', 'Revisa la evaluación de entregas de almacén y el cumplimiento del programa de mantenimiento a su cargo.'),
    ('CAF', 12, 'Elaborar y analizar indicadores de desempeño.', 'M', 'RR', 'Calcula e interpreta los indicadores de su proceso y propone acción cuando no se alcanza la meta.'),
    ('CAF', 13, 'Manejar XLAB, XLAB Inventario, sistemas contables y banca electrónica autorizada.', 'M', 'EP', 'Opera en XLAB Inventario la generación y notificación de una orden de compra y consulta el seguimiento de entregas.'),
    ('CAF', 14, 'Utilizar hojas de cálculo y herramientas digitales para análisis y control.', 'B', 'EP', 'Elabora en hoja de cálculo el resumen de ingresos de facturas y lo cuadra con el reporte del despacho contable.'),
    ('CAF', 15, 'Elaborar reportes financieros y administrativos claros, exactos y oportunos.', 'M', 'RR', 'Entrega un reporte financiero completo, exacto y en la fecha pactada con la Dirección General.'),
    ('CAF', 16, 'Preparar evidencia para auditorías internas, externas y evaluaciones EMA.', 'M', 'OD', 'Ante una auditoría simulada, localiza y presenta la evidencia de selección, evaluación y contratos de proveedores.'),
    ('CAF', 17, 'Aplicar controles de confidencialidad y protección de información.', 'M', 'OD', 'Restringe el acceso a información bancaria, fiscal o contractual a personal no autorizado durante su trabajo diario.'),
    ('CAF', 18, 'Gestionar acciones correctivas y oportunidades de mejora.', 'M', 'RR', 'Muestra una no conformidad de su proceso con su análisis de causa, acción correctiva y verificación de eficacia.'),
    ('CCM', 1, 'Interpretación y aplicación de los requisitos de la Norma ISO 15189:2022 y de la documentación del Sistema de Gestión de la Calidad relacionada con las actividades bajo su responsabilidad.', 'M', 'ES', 'Resuelve casos sobre retroalimentación, quejas, uso del símbolo de acreditación y contratos conforme a los procedimientos de su proceso.'),
    ('CCM', 2, 'Conocimiento de los servicios, procesos y modelo de atención que ofrece el laboratorio clínico.', 'M', 'OD', 'Ante una consulta simulada de una empresa, localiza en el catálogo vigente el examen, la muestra, la preparación y el tiempo de entrega, y canaliza lo técnico al personal autorizado.'),
    ('CCM', 3, 'Conocimiento de los procesos de comercialización, mercadotecnia, relaciones públicas y desarrollo de negocios.', 'M', 'RR', 'Presenta el plan comercial vigente con objetivos, responsables, indicadores y seguimiento, y el reporte de campañas entregado a la Dirección General.'),
    ('CCM', 4, 'Atención, servicio y seguimiento a clientes, médicos, empresas e instituciones, orientado a la satisfacción del usuario.', 'A', 'OD', 'Recibe un comentario de un cliente, lo registra de manera textual y lo canaliza al Coordinador del Sistema de Gestión de la Calidad sin prometer resultados.'),
    ('CCM', 5, 'Técnicas de negociación, desarrollo comercial, establecimiento y seguimiento de convenios institucionales.', 'M', 'RR', 'Muestra un convenio formalizado con su revisión, la autorización de la Dirección General, la difusión a las áreas y el registro de su vigencia.'),
    ('CCM', 6, 'Manejo, análisis e interpretación de indicadores de desempeño (KPI), elaboración de reportes ejecutivos y evaluación de resultados comerciales.', 'M', 'RR', 'Interpreta el indicador de satisfacción del periodo contra su meta y propone la acción que corresponde cuando no se alcanza.'),
    ('CCM', 7, 'Manejo de Microsoft Office (Word, Excel, PowerPoint y Outlook) para la elaboración de reportes, análisis de información y presentaciones ejecutivas.', 'B', 'RR', 'Elabora en hoja de cálculo el comparativo de ingresos de los dos años anteriores y lo presenta en formato ejecutivo.'),
    ('CCM', 8, 'Manejo del Sistema de Información del Laboratorio (LIS) utilizado por el laboratorio para las funciones inherentes al puesto.', 'M', 'OD', 'Captura en el sistema la calificación de las encuestas físicas y los datos de los médicos nuevos detectados en el recibo, dentro de su perfil autorizado.'),
    ('CCM', 9, 'Conocimiento y aplicación de los procedimientos, instructivos, políticas y registros del Sistema de Gestión de la Calidad relacionados con su proceso.', 'M', 'RR', 'Se verifica que las encuestas, las retroalimentaciones y su análisis se llevan conforme al procedimiento y quedan en los registros que éste fija.'),
    ('CCM', 10, 'Comunicación oral y escrita efectiva para la atención de usuarios, coordinación interdepartamental y representación institucional.', 'B', 'OD', 'Comunica a recepción y facturación las condiciones de un convenio nuevo de forma clara y completa.'),
    ('CCM', 11, 'Conocimiento y manejo de herramientas para el diseño, edición y administración de material publicitario, contenido digital y medios de comunicación institucional.', 'B', 'EP', 'Elabora un tríptico o una publicación con información de estudios tomada del catálogo vigente y lo somete a revisión antes de difundirlo.'),
    ('CCM', 12, 'Análisis estadístico básico, interpretación de indicadores y elaboración de información para la toma de decisiones.', 'M', 'RR', 'Calcula el número de encuestas, el promedio por pregunta y la tendencia del mes, e identifica los comentarios relevantes.'),
    ('CCM', 13, 'Organización, coordinación y seguimiento de eventos corporativos, campañas de promoción y relaciones institucionales.', 'M', 'RR', 'Muestra un evento aceptado por el cliente y notificado al Coordinador de Servicios Especiales con la información completa.'),
    ('CCM', 14, 'Manejo de redes sociales, plataformas digitales y herramientas de comunicación para la difusión de los servicios institucionales, conforme a las políticas del laboratorio.', 'M', 'OD', 'Ante mensajes simulados en redes sociales con una cotización y una queja, canaliza la cotización a recepción y la queja al proceso institucional, sin exponer datos del paciente.'),
    ('CCM', 15, 'Conocimiento de la normatividad aplicable en materia de publicidad de servicios de salud y de los procedimientos institucionales para la gestión de permisos y autorizaciones cuando corresponda.', 'A', 'OD', 'Revisa un borrador de anuncio, detecta si alude a la acreditación, hace promesas clínicas o comparaciones no demostrables, y define qué autorización requiere antes de publicarse.'),
    ('CPA', 1, 'Interpretación y aplicación integral de la Norma ISO 15189:2022.', 'M', 'OD', 'Relaciona un hallazgo de un área analítica con el requisito aplicable y con el procedimiento de UNILABOR que lo atiende (control interno, evaluación externa, verificación, incertidumbre).'),
    ('CPA', 2, 'Planeación y coordinación de procesos analíticos multidisciplinarios.', 'M', 'RR', 'Revisa la cobertura de turnos y la asignación de personal por área contra el listado de personal autorizado, y la disponibilidad de equipos del día.'),
    ('CPA', 3, 'Diseño y evaluación de programas de aseguramiento de la validez de los resultados.', 'A', 'RR', 'Revisa la selección de TEa por sigma, el plan de participación en ensayos de aptitud y su revisión cada doce meses, y el seguimiento mensual de indicadores de desempeño.'),
    ('CPA', 4, 'Validación y verificación de métodos analíticos.', 'A', 'RR', 'Revisa y autoriza un informe de verificación: especificaciones a alcanzar, resultados y declaración de cumplimiento o acción tomada; ante un criterio no cumplido, levanta la no conformidad y ordena repetir.'),
    ('CPA', 5, 'Autorización y evaluación del personal signatario.', 'A', 'RR', 'Verifica que cada signatario cuente con evaluación de competencia aprobada y carta de asignación antes de liberar resultados, y que la evaluación continua se haya hecho en los últimos doce meses.'),
    ('CPA', 6, 'Aplicación e interpretación del control estadístico de la calidad (reglas de Westgard, gráficos de Levey-Jennings).', 'A', 'OD', 'Ante una serie de gráficos de Levey-Jennings del área, identifica la regla violada según las reglas asignadas por sigma, contiene el error interrumpiendo pacientes, no elimina el punto rechazado y define qué pacientes reanalizar desde el último evento en control.'),
    ('CPA', 7, 'Validación técnica y liberación de resultados.', 'A', 'RR', 'En bitácoras recientes del colaborador, comprueba que los resultados en verificación llevan (*) y (*v), que los liberados llevan (LIB) con iniciales, y que la diferencia entre primer resultado y reproceso no excedió el 5 %.'),
    ('CPA', 8, 'Verificación del desempeño de métodos y equipos analíticos.', 'A', 'RR', 'Explica y revisa un estudio de verificación del área: réplicas de precisión, criterio de 0,25 o 0,33 del error total, linealidad con puntos de decisión clínica, y la acción cuando un criterio no se cumple.'),
    ('CPA', 9, 'Trazabilidad metrológica y manejo de materiales de referencia.', 'M', 'RR', 'Localiza la carta de trazabilidad de un analito del alcance, identifica el material de referencia de mayor orden y su incertidumbre, y explica cuándo es aceptable la trazabilidad declarada por el fabricante.'),
    ('CPA', 10, 'Investigación de desviaciones, trabajo no conforme y análisis de causa raíz.', 'A', 'OD', 'Sobre un caso de control fuera de criterio, aplica detener y retener, determina el alcance desde el último punto bajo control, gradúa el significado clínico, documenta el evento y enlaza la causa raíz por folio.'),
    ('CPA', 11, 'Gestión documental y control de registros.', 'M', 'RR', 'Verifica que los registros del área que llena el colaborador estén completos, legibles y trazables, en su versión vigente, y que las correcciones conservan el dato original.'),
    ('CPA', 12, 'Gestión de riesgos aplicada al proceso analítico.', 'M', 'OD', 'Ubica en la matriz los riesgos del área a su cargo y explica los controles vigentes, y propone el registro de un riesgo nuevo detectado en un caso de falla de equipo o desabasto.'),
    ('CPA', 13, 'Manejo del sistema de información del laboratorio.', 'M', 'OD', 'Ejecuta en X-Lab y AMS la revisión de resultados, el envío a verificación (reanálisis) y la liberación por analito o por paciente, con su usuario y contraseña.'),
    ('CPP', 1, 'Interpretación y aplicación de la Norma ISO 15189:2022, con énfasis en los apartados 6.2, 7.2 y 7.5.', 'M', 'OD', 'Ante casos del proceso (muestra comprometida, solicitud verbal, cambio de método) identifica qué documento del mapa documental es dueño de la decisión y la resuelve conforme a él.'),
    ('CPP', 2, 'Diseño y control de procesos preanalíticos.', 'M', 'RR', 'Prepara la entrada de la revisión anual de volumen, dispositivo y conservantes contrastando el catálogo y el manual de toma contra las especificaciones del fabricante.'),
    ('CPP', 3, 'Establecimiento y verificación de criterios de aceptación y rechazo de muestras.', 'A', 'RR', 'Revisa el registro de muestras rechazadas, analiza causas y deja registrada la valoración de cada aceptación por excepción.'),
    ('CPP', 4, 'Supervisión técnica y evaluación de la competencia del personal.', 'A', 'RR', 'Mantiene la relación del personal autorizado por escrito para evaluar muestras y realiza supervisiones documentadas en campo.'),
    ('CPP', 5, 'Control de condiciones de conservación y transporte de muestras.', 'A', 'RR', 'Documenta la evaluación anual del transporte: tiempos, intervalo de temperatura, integridad a la llegada, incidentes y autorización del personal.'),
    ('CPP', 6, 'Elaboración y análisis de indicadores de calidad del proceso preexamen.', 'M', 'RR', 'Calcula y analiza los indicadores declarados (rechazo y causa, aclaraciones, tiempos y temperatura de traslado, aceptaciones por excepción) y los lleva a la revisión por la dirección.'),
    ('CPP', 7, 'Investigación de desviaciones, análisis de causa raíz y gestión de acciones correctivas.', 'M', 'RR', 'Da seguimiento a las incidencias preanalíticas como trabajo no conforme y, cuando lo requieren, abre acción correctiva hasta verificar su eficacia.'),
    ('CPP', 8, 'Gestión documental y control de registros.', 'M', 'RR', 'Durante la supervisión comprueba que el personal de cada sede tiene acceso efectivo a la versión vigente de los documentos del proceso.'),
    ('CPP', 9, 'Manejo del sistema de información del laboratorio (X-Lab).', 'M', 'OD', 'Verifica que un cambio publicado en el catálogo documentado quede reflejado en el catálogo del sistema X-LAB.'),
    ('CRH', 1, 'Interpretar y aplicar los requisitos de ISO 15189:2022 relacionados con personal, competencia, autorización, imparcialidad, confidencialidad y registros.', 'A', 'OD', 'Ante un expediente de prueba, identifica qué evidencia falta para autorizar al colaborador (perfil, inducción, Fase 7, carta de asignación, confidencialidad) y qué numeral del REH-MAN-002 Manual de Gestión de Personal la exige.'),
    ('CRH', 2, 'Elaborar, revisar y controlar perfiles y descripciones de puesto.', 'M', 'RR', 'Revisa una descripción de puesto y detecta requisitos, autoridades o códigos citados que no concuerdan con las listas maestras; propone el cambio por control de documentos.'),
    ('CRH', 3, 'Ejecutar procesos de reclutamiento, selección y contratación con criterios definidos y evidencia objetiva.', 'M', 'RR', 'Conduce o documenta una selección: entrevista registrada, preevaluación aplicada y decisión con sustento contra el perfil.'),
    ('CRH', 4, 'Verificar la autenticidad, suficiencia y vigencia de documentos de formación y experiencia.', 'A', 'RR', 'Coteja título, cédula, constancias y cartas laborales contra el perfil del puesto y deja constancia de la verificación en el expediente.'),
    ('CRH', 5, 'Planear y controlar la inducción, entrenamiento, capacitación y desarrollo del personal.', 'M', 'RR', 'Programa las fases de inducción de un ingreso, notifica a los responsables de fase y verifica que cada fase quede documentada.'),
    ('CRH', 6, 'Diseñar y administrar evaluaciones de competencia y desempeño con criterios objetivos y trazables.', 'A', 'EP', 'Integra una evaluación con parte teórica y práctica, criterio de 80 % en cada una, evidencia objetiva, firmas, fecha y decisión documentada.'),
    ('CRH', 7, 'Controlar autorizaciones, restricciones, suspensiones y reevaluaciones del personal.', 'A', 'RR', 'Mantiene al día el alcance, la fecha y las restricciones de cada autorización y da de baja o restringe las vencidas o suspendidas.'),
    ('CRH', 8, 'Integrar, proteger, conservar y recuperar expedientes laborales y de competencia.', 'M', 'OD', 'Localiza y entrega un expediente solicitado en tiempo, registra la consulta o préstamo y restringe el acceso a personal no autorizado.'),
    ('CRH', 9, 'Elaborar la Detección de Necesidades y el Programa Anual de Capacitación.', 'M', 'RR', 'Integra las necesidades detectadas por las áreas y las traslada al programa con temas, responsables, fechas y método de evaluación de eficacia.'),
    ('CRH', 10, 'Evaluar y documentar la eficacia de la capacitación.', 'M', 'RR', 'Calcula el porcentaje de cumplimiento del programa y el promedio de las evaluaciones del periodo, los compara contra el 80 % y documenta el análisis cuando no se alcanza.'),
    ('CRH', 11, 'Administrar incidencias, vacaciones, permisos, incapacidades, suplencias, movimientos y bajas.', 'B', 'RR', 'Tramita una solicitud de vacaciones y su suplencia dentro de los plazos del instructivo, con suplente competente y autorizado.'),
    ('CRH', 12, 'Aplicar legislación laboral y políticas institucionales dentro de su ámbito de competencia.', 'M', 'OD', 'Resuelve un caso de incidencia laboral (retardos, permisos o incapacidad) aplicando el REH-INS-001 Reglamento Interno de Trabajo sin exceder su autoridad.'),
    ('CRH', 13, 'Elaborar y analizar indicadores de Recursos Humanos.', 'M', 'RR', 'Reporta rotación, ausentismo, capacitación y autorizaciones del periodo, identifica la tendencia y explica la desviación.'),
    ('CRH', 14, 'Identificar riesgos de competencia, cobertura, imparcialidad y continuidad operativa.', 'M', 'OD', 'Ante un escenario de ausencia de un puesto crítico sin suplente autorizado, identifica el riesgo y propone su control para la matriz.'),
    ('CRH', 15, 'Gestionar acciones correctivas y oportunidades de mejora relacionadas con el personal.', 'M', 'RR', 'Documenta una desviación de personal, participa en el análisis de causa y da seguimiento al cierre con evidencia.'),
    ('CRH', 16, 'Preparar y presentar evidencia documental durante auditorías y evaluaciones EMA.', 'M', 'OD', 'En una auditoría simulada, presenta para un colaborador elegido al azar la cadena perfil, inducción, evaluación, autorización y capacitación continua.'),
    ('CRH', 17, 'Manejar herramientas ofimáticas, hojas de cálculo, bases de datos y sistemas institucionales de Recursos Humanos.', 'B', 'OD', 'Captura y consulta expedientes y capacitaciones en la plataforma institucional sin errores de captura.'),
    ('CRH', 18, 'Redactar oficios, comunicados, actas, informes y documentos laborales con claridad y control documental.', 'B', 'RR', 'Redacta un aviso o comunicado interno claro, con código vigente, fecha y firma.'),
    ('CSE', 1, 'Interpretación y aplicación de los requisitos de la Norma ISO 15189:2022 y de los procedimientos del Sistema de Gestión de la Calidad aplicables a su proceso.', 'M', 'OD', 'Antes de formalizar un servicio revisa y acuerda requisitos del laboratorio, del cliente y legales, y considera los riesgos del servicio en sitio.'),
    ('CSE', 2, 'Conocimiento integral de los servicios que ofrece el laboratorio, sus condiciones de prestación, requisitos preanalíticos y criterios para la programación de servicios especiales.', 'M', 'OD', 'Resuelve qué preparación, tipo de muestra y tiempo de entrega aplican a los estudios de un contrato consultando el catálogo.'),
    ('CSE', 3, 'Planeación, organización y coordinación logística de servicios de toma de muestras extramuros y eventos especiales.', 'M', 'RR', 'Planea personal, equipo y materiales del evento a partir de la notificación y del listado del cliente.'),
    ('CSE', 4, 'Conocimiento de los requisitos para la preparación del paciente, toma, identificación, conservación, transporte, recepción y entrega de muestras biológicas, conforme a los procedimientos institucionales.', 'A', 'OD', 'Supervisa que las neveras se mantengan de 2 a 8 °C, que su temperatura se registre cada hora y al salir, y que las muestras lleguen con su lista a Separación y Distribución.'),
    ('CSE', 5, 'Atención, comunicación y servicio al cliente, incluyendo la gestión de requerimientos de empresas, instituciones y usuarios.', 'M', 'OD', 'Coordina con el cliente los aspectos operativos, obtiene el listado y el enlace designado.'),
    ('CSE', 6, 'Coordinación, supervisión y seguimiento del desempeño del personal bajo su responsabilidad.', 'M', 'RR', 'Asigna como custodios sólo a personal con capacitación, competencia y autorización vigentes.'),
    ('CSE', 7, 'Manejo de Microsoft Office y herramientas digitales para la elaboración de reportes, indicadores y control operativo.', 'B', 'RR', 'Elabora los reportes de cierre del servicio con las herramientas institucionales.'),
    ('CSE', 8, 'Conocimiento y aplicación de los principios de bioseguridad, seguridad e higiene, manejo de RPBI y gestión de riesgos aplicables a las actividades bajo su responsabilidad.', 'M', 'OD', 'En el evento verifica EPP del personal, segregación de RPBI y los controles de riesgo previstos.'),
    ('CSE', 9, 'Conocimiento de los procedimientos de cadena de custodia aplicables a los estudios que así lo requieran.', 'A', 'RR', 'Revisa que cada TOX-REG-001 Evaluación toxicológica- Autorización, cuestionario de ingesta de medicamentos o tratamientos previos lleve nombre y firma del custodio y que las muestras correspondan con la documentación y los registros de temperatura al recibirlas del custodio de nevera.'),
    ('CSE', 10, 'Manejo del Sistema de Información del Laboratorio (LIS) utilizado por la organización para la programación, seguimiento y consulta de los servicios.', 'A', 'OD', 'Crea el contrato en X-LAB Móvil, importa en XLAB con usuario UNIDAD CENTRO, verifica que las pruebas del contrato estén asignadas (casillas en azul) y genera plantillas y bitácora.'),
    ('CSE', 11, 'Conocimiento y aplicación de los procedimientos, políticas, instructivos y registros del Sistema de Gestión de la Calidad relacionados con su proceso.', 'M', 'RR', 'Integra el expediente del evento con los registros que generan los procedimientos aplicados.'),
    ('CSE', 12, 'Conocimiento de la gestión documental, control de registros, manejo de información confidencial y protección de datos personales aplicables a los servicios especiales.', 'M', 'RR', 'Exporta resultados digitales del contrato a USB nombrados por folio XLAB y los entrega según lo que estipula el contrato.'),
    ('CSI', 1, 'Administración de Sistemas de Información del Laboratorio (SIL/LIS), garantizando su disponibilidad, integridad, confidencialidad y continuidad operativa.', 'A', 'OD', 'Opera el sistema XLAB en una actividad real: tramita un alta o baja de usuario con la autorización correspondiente, revisa la disponibilidad del servicio y registra cualquier incidencia.'),
    ('CSI', 2, 'Administración y gestión de bases de datos relacionales, incluyendo PostgreSQL, MariaDB, MySQL, Microsoft SQL Server, Oracle o tecnologías equivalentes.', 'A', 'EP', 'Ejecuta ante el evaluador una consulta, un respaldo y una restauración de prueba de la base de datos, sin operar sobre datos de producción.'),
    ('CSI', 3, 'Desarrollo, mantenimiento e implementación de aplicaciones web mediante lenguajes y frameworks de programación modernos (Delphi, HTML, CSS, Tailwind CSS, JavaScript, TypeScript, React, Next.js o tecnologías equivalentes).', 'M', 'RR', 'Muestra un cambio reciente desarrollado fuera de producción, con sus pruebas documentadas, su identificación de versión y su previsión de reversión.'),
    ('CSI', 4, 'Administración de servidores Linux y Windows Server, incluyendo instalación, configuración, actualización, monitoreo y mantenimiento.', 'M', 'OD', 'Aplica o simula una actualización de sistema operativo evaluando antes su efecto sobre los equipos conectados a analizadores, y documenta la intervención.'),
    ('CSI', 5, 'Administración de servidores web y servicios asociados (Apache, Nginx o tecnologías equivalentes).', 'M', 'EP', 'Diagnostica una falla planteada del servicio web de consulta de resultados y restablece su funcionamiento, registrando la causa y el tiempo de restablecimiento.'),
    ('CSI', 6, 'Administración de infraestructura virtualizada y servidores privados virtuales (VPS), incluyendo el despliegue y mantenimiento de aplicaciones institucionales.', 'M', 'RR', 'Muestra dónde reside la información alojada en infraestructura de terceros, qué medidas de protección se le aplican y la evidencia de respaldo del proveedor.'),
    ('CSI', 7, 'Administración de redes, servicios de comunicación y conectividad necesarios para la operación del laboratorio.', 'M', 'OD', 'Explica y muestra la separación de la red de los equipos de medición respecto de la red administrativa y de acceso público, y la conexión cifrada entre sedes.'),
    ('CSI', 8, 'Mantenimiento preventivo, correctivo y diagnóstico de equipos de cómputo e infraestructura tecnológica.', 'M', 'RR', 'Ejecuta el mantenimiento preventivo programado de un equipo de cómputo y documenta lo realizado y los hallazgos; atiende un correctivo y lo registra.'),
    ('CSI', 9, 'Gestión, verificación y recuperación de respaldos de información, garantizando la disponibilidad y continuidad de los datos institucionales.', 'A', 'EP', 'Realiza una prueba de restauración de un respaldo de un sistema crítico y documenta su resultado, no sólo que la copia se ejecutó.'),
    ('CSI', 10, 'Diseño, implementación, mantenimiento y evaluación de planes de contingencia y recuperación ante desastres para los sistemas de información.', 'A', 'OD', 'Conduce un simulacro de caída del sistema: activa el plan, aplica los mecanismos alternos en papel y verifica el restablecimiento sin pérdida ni duplicidad de registros.'),
    ('CSI', 11, 'Validación, gestión de cambios y documentación de sistemas informáticos conforme a los procedimientos institucionales y a los requisitos de la Norma ISO 15189:2022.', 'A', 'RR', 'Presenta el expediente de un cambio que afecta parámetros del resultado: evaluación previa, pruebas, autorización y verificación de funcionalidad por el responsable de proceso.'),
    ('CSI', 12, 'Conocimiento de los requisitos de gestión de la información, seguridad de la información y continuidad operativa establecidos en la Norma ISO 15189:2022 y demás disposiciones aplicables.', 'M', 'ES', 'Resuelve por escrito casos sobre validación y verificación, control de cambios, respaldos y contingencia conforme al procedimiento.'),
    ('CSI', 13, 'Administración de controles de acceso, seguridad informática, monitoreo y protección de la infraestructura tecnológica.', 'A', 'RR', 'Hace la revisión periódica de perfiles: compara los permisos vigentes contra la matriz autorizada y tramita las bajas pendientes por cambio de puesto.'),
    ('CSI', 14, 'Capacidad para interpretar documentación técnica en inglés relacionada con sistemas operativos, bases de datos, infraestructura tecnológica y Sistemas de Información del Laboratorio.', 'B', 'EP', 'Lee un fragmento de documentación técnica en inglés del proveedor (requisitos de entorno o notas de versión) y explica qué implica para el sistema del laboratorio.'),
    ('CSGC', 1, 'Interpretación y aplicación de la norma ISO 15189:2022.', 'A', 'OD', 'Ante hallazgos simulados, identifica el requisito de la ISO 15189:2022 aplicable y si el hecho lo cumple o no.'),
    ('CSGC', 2, 'Sistemas de gestión de calidad (ISO 9001, ISO 15189, etc.).', 'M', 'OD', 'Relaciona un proceso del laboratorio con los documentos y registros del sistema que lo controlan.'),
    ('CSGC', 3, 'Auditorías internas y metodologías de mejora continua (PDCA, Lean, Six Sigma).', 'A', 'RR', 'Elabora el programa y el plan de auditoría con alcance, criterios, auditores independientes y calendario.'),
    ('CSGC', 4, 'Elaboración y control de documentación del sistema.', 'A', 'RR', 'Controla la emisión de un documento: revisión, aprobación, alta en la lista maestra, distribución con acuse y retiro de la versión anterior.'),
    ('CSGC', 5, 'Indicadores de gestión de calidad y tableros de control.', 'M', 'RR', 'Calcula e interpreta los indicadores contra su meta e identifica tendencias y desviaciones.'),
    ('CSGC', 6, 'Competencias en liderazgo, trabajo en equipo y comunicación efectiva.', 'M', 'OD', 'Conduce una reunión de seguimiento con responsables de proceso y deja acuerdos con responsable y fecha.'),
    ('CSGC', 7, 'Manejo de herramientas digitales para gestión documental y de calidad.', 'M', 'EP', 'Publica, consulta y recupera documentos y registros en la plataforma institucional sin alterar versiones.'),
    ('CSGC', 8, 'Conocimientos en auditoría interna y externa', 'A', 'RR', 'Registra hallazgos con requisito, evidencia y clasificación, y da seguimiento a los de auditorías internas y externas.'),
    ('CSGC', 9, 'Conocimiento en metodologías para el análisis de causas raíz y solución de problemas (Ishikawa, 5 por qué).', 'A', 'OD', 'Aplica los 5 Porqués o Ishikawa a una no conformidad simulada y distingue la causa raíz de los síntomas.'),
    ('CSGC', 10, 'Conocimiento en análisis masivo de datos a través herramientas como power BI', 'B', 'EP', 'Construye un tablero o resumen a partir de los datos de indicadores o de no conformidades.'),
    ('CSGC', 11, 'Conocimiento de herramienta de gestión Balanced Scorecard', 'B', 'OD', 'Ordena los objetivos de calidad del periodo por perspectiva y los vincula con su indicador y meta.'),
    ('CSGC', 12, 'Conocimiento de indicadore de desempeño KPI´S', 'M', 'RR', 'Define para un proceso el indicador, la fórmula, la frecuencia y la meta, y lo compara con el resultado.'),
    ('CSGC', 13, 'Dominio de guía CLSI c24 a4', 'M', 'OD', 'Ante un caso de control de calidad interno, identifica la regla de control aplicable y la acción sobre la corrida.'),
    ('CSGC', 14, 'Manejo de paquetería office', 'B', 'EP', 'Elabora en hoja de cálculo y procesador de textos un reporte de indicadores para la Dirección.'),
    ('CSGC', 15, 'Nivel medio de estadística cuantitativa.', 'M', 'EP', 'Calcula media, desviación estándar y porcentajes de un conjunto de datos del sistema e interpreta el resultado.'),
    ('CSGC', 16, 'Conocimiento en gestión de operaciones y procesos', 'M', 'OD', 'Describe un proceso del laboratorio con sus entradas, salidas, responsables y controles, y señala un punto de mejora.'),
    ('CUST', 1, 'Identificación correcta del paciente.', 'A', 'OD', 'Verifica que el nombre de las etiquetas coincida exactamente con la identificación oficial, obtiene firma en el Recibo, firma y huella en el TOX-REG-001 Evaluación toxicológica- Autorización, cuestionario de ingesta de medicamentos o tratamientos previos y firma de las etiquetas con tinta azul.'),
    ('CUST', 2, 'Manejo de cadena de custodia.', 'A', 'OD', 'Acompaña, retiene la identificación, explica la recolección bajo observación directa, no pierde de vista al paciente ni la muestra y transfiere formalmente la custodia.'),
    ('CUST', 3, 'Criterios de aceptación y rechazo de muestras.', 'A', 'OD', 'Ante casos de temperatura, volumen o aspecto sospechoso decide válida o no válida según el procedimiento y notifica al Coordinador de Procedimientos Preanalíticos cuando hay sospecha de adulteración.'),
    ('CUST', 4, 'Etiquetado y trazabilidad de muestras.', 'A', 'OD', 'Verifica el sellado en diadema, registra que los contenedores se etiquetaron, cerraron y sellaron en su presencia y el color de la muestra.'),
    ('CUST', 5, 'Aplicación de medidas de bioseguridad.', 'M', 'OD', 'Considera toda muestra potencialmente infecciosa, pide al paciente lavarse las manos y maneja los residuos conforme al procedimiento de RPBI.'),
    ('CUST', 6, 'Uso adecuado de equipo de protección personal.', 'M', 'OD', 'Usa bata, cubrebocas y guantes durante la recolección y el manejo de la muestra.'),
    ('CUST', 7, 'Cumplimiento de procedimientos documentados.', 'M', 'RR', 'Los registros de cadena de custodia de sus pacientes están llenos en tiempo real, con su nombre y firma.'),
    ('DG', 1, 'Planeación y dirección estratégica.', 'A', 'OD', 'A partir de los resultados del periodo, define metas y prioridades y asigna responsables, recursos y plazos a cada una.'),
    ('DG', 2, 'Administración de recursos humanos, financieros, tecnológicos y materiales.', 'A', 'RR', 'Revisa y aprueba el presupuesto y la asignación de recursos con base en las necesidades presentadas por las coordinaciones.'),
    ('DG', 3, 'Interpretación de requisitos legales, normativos y de acreditación.', 'A', 'OD', 'Ante un caso planteado, identifica el requisito legal, normativo o de acreditación aplicable y la decisión que corresponde a la Dirección.'),
    ('DG', 4, 'Gestión institucional de riesgos y oportunidades.', 'A', 'RR', 'Revisa la matriz, distingue los riesgos no aceptables y aprueba el tratamiento, el responsable y el plazo.'),
    ('DG', 5, 'Gestión de la imparcialidad y confidencialidad.', 'A', 'OD', 'Ante un caso de presión comercial o de relación personal, identifica la amenaza a la imparcialidad y la medida de control que aprueba.'),
    ('DG', 6, 'Evaluación de indicadores y desempeño organizacional.', 'A', 'RR', 'Interpreta el reporte de indicadores, identifica los que no alcanzan la meta y solicita el plan de acción.'),
    ('DG', 7, 'Revisión de la eficacia del Sistema de Gestión de la Calidad.', 'A', 'RR', 'Emite un pronunciamiento expreso sobre la eficacia del sistema con base en las entradas de la revisión.'),
    ('DG', 8, 'Dirección de la revisión por la dirección.', 'A', 'OD', 'Preside la sesión, verifica el quórum requerido, conduce el orden del día y registra decisiones con responsable, recurso y plazo.'),
    ('DG', 9, 'Gestión de cambios organizacionales.', 'M', 'OD', 'Ante un cambio de estructura o de puesto propuesto, evalúa sus efectos y los riesgos antes de autorizarlo.'),
    ('DG', 10, 'Gestión de proveedores y servicios externos.', 'A', 'RR', 'Revisa la evaluación del proveedor o del laboratorio subcontratado y decide su aprobación o continuidad.'),
    ('DG', 11, 'Continuidad operativa y respuesta ante contingencias.', 'A', 'OD', 'Ante una falla simulada de energía, sistema o equipo crítico, decide la suspensión, restricción o reanudación de actividades y los recursos.'),
    ('DG', 12, 'Seguimiento de auditorías, acciones correctivas y oportunidades de mejora.', 'A', 'RR', 'Verifica el estado de cierre de las acciones correctivas y la evidencia de su eficacia.'),
    ('DG', 13, 'Evaluación del desempeño de las coordinaciones.', 'M', 'RR', 'Evalúa a los coordinadores que le reportan con base en objetivos, indicadores y resultados, con criterios documentados.'),
    ('DG', 14, 'Toma de decisiones basada en evidencia.', 'A', 'OD', 'Sustenta cada decisión de un caso en datos verificables (indicadores, hallazgos, quejas) y la deja documentada.'),
    ('FLEB', 1, 'Identificación correcta del paciente.', 'A', 'OD', 'Corrobora frente al paciente nombre completo, fecha de nacimiento, estudios y demás datos del numeral 6.1, y le muestra las etiquetas de los tubos para que confirme su identidad.'),
    ('FLEB', 2, 'Técnicas de flebotomía.', 'A', 'OD', 'Coloca el torniquete a unos 10 cm y menos de 1 minuto, desinfecta, fija la vena, elige la aguja según calibre de vena y número de tubos, y libera el torniquete antes de retirar la aguja.'),
    ('FLEB', 3, 'Orden de extracción de tubos.', 'A', 'OD', 'Llena los tubos en el orden del cartel de la toma y del fabricante, cuida el aforo y homogeniza cada tubo con el número de inversiones que corresponde.'),
    ('FLEB', 4, 'Manejo y conservación de muestras biológicas.', 'A', 'OD', 'Verifica identificación e integridad, coloca las muestras en la gradilla que corresponde y deja el Recibo en la bandeja del área de Separación y Distribución.'),
    ('FLEB', 5, 'Criterios de aceptación y rechazo de muestras.', 'A', 'OD', 'Ante casos (tubo incorrecto, coágulo en tubo anticoagulado, volumen insuficiente, tubo sin etiqueta) reconoce el criterio de rechazo y no entrega la muestra como válida.'),
    ('FLEB', 6, 'Etiquetado y trazabilidad de muestras.', 'A', 'OD', 'Etiqueta los tubos en presencia del paciente y se los muestra; registra iniciales, R.V., cubículo e indicaciones en el Recibo.'),
    ('FLEB', 7, 'Atención segura al paciente.', 'A', 'OD', 'Aplica las preguntas de la Carta de consentimiento (ayuno, medicamentos, desmayos, alergias) y, al terminar, verifica que la hemorragia esté controlada y que el paciente no esté mareado.'),
    ('FLEB', 8, 'Manejo de contingencias durante la toma de muestras.', 'A', 'OD', 'En simulación de síncope o de extravasación ejecuta la secuencia del manual y sabe cuándo pedir apoyo médico.'),
    ('FLEB', 9, 'Aplicación de medidas de bioseguridad.', 'M', 'OD', 'Limpia mesa, torundero y lapicero con alcohol al 70 %, desinfecta el torniquete y realiza la higiene de manos visible frente al paciente.'),
    ('FLEB', 10, 'Uso adecuado de equipo de protección personal.', 'M', 'OD', 'Porta identificación, bata y cubrebocas; usa careta en tomas faríngeas, nasales y nasofaríngeas, y guantes en tomas para cultivo.'),
    ('FLEB', 11, 'Manejo de RPBI.', 'M', 'OD', 'Desecha la aguja de inmediato en el contenedor de punzocortantes y los algodones con sangre en la bolsa de RPBI.'),
    ('FLEB', 12, 'Cumplimiento de procedimientos documentados.', 'M', 'RR', 'Los Recibos y Cartas de consentimiento de sus tomas están completos: iniciales, firma, verificación de la orden, cubículo, cumplimiento de indicaciones, número y zona de punción.'),
    ('LAV', 1, 'Lavado y desinfección de material reutilizable.', 'A', 'OD', 'Procesa material reutilizable siguiendo para cada tipo la secuencia desmanchar y vaciar, inactivar, enjuagar, lavar, enjuagar y secar del Anexo 5 del PRE-MAN-001 Manual de Seguridad e Higiene.'),
    ('LAV', 2, 'Manejo seguro de material contaminado.', 'A', 'OD', 'Vacía el contenido de tubos al recipiente para RPBI y sumerge el material en hipoclorito al 0.5 % el tiempo indicado antes de manipularlo para lavado.'),
    ('LAV', 3, 'Uso correcto de detergentes y desinfectantes.', 'M', 'OD', 'Prepara hipoclorito al 0.5 % a partir del producto comercial con las proporciones del Anexo 4 y elige el producto correcto según el material (sin cloro para anteojos y caretas).'),
    ('LAV', 4, 'Aplicación de medidas de bioseguridad.', 'M', 'RR', 'Trabaja con el área ordenada, sin alimentos, con contenedores de RPBI identificados y sin rebasar su límite de llenado.'),
    ('LAV', 5, 'Uso adecuado de equipo de protección personal.', 'M', 'OD', 'Usa bata, guantes, cubrebocas y protección ocular durante el vaciado e inactivación, y los retira sin contaminarse.'),
    ('LAV', 6, 'Prevención de contaminación cruzada.', 'A', 'OD', 'Separa físicamente el material sucio del limpio, no regresa material sin terminar el ciclo y entrega sólo material completamente procesado.'),
    ('LAV', 7, 'Manejo y almacenamiento de material limpio.', 'M', 'OD', 'Almacena el material seco en el lugar asignado, protegido de polvo y humedad, y lo entrega a las áreas que lo solicitan.'),
    ('LAV', 8, 'Identificación de material dañado o no apto para uso.', 'M', 'OD', 'Ante una muestra de material con grietas, residuos o manchas, separa el no apto y lo reporta.'),
    ('LAV', 9, 'Limpieza y desinfección de áreas y equipos relacionados.', 'M', 'RR', 'Limpia y desinfecta tarjas, superficies y equipos del área al inicio y al término de la jornada y lo registra.'),
    ('LAV', 10, 'Cumplimiento de procedimientos documentados.', 'M', 'RR', 'Ejecuta los tiempos y concentraciones de los procedimientos vigentes sin atajos y consulta la versión vigente en SafeDoc.'),
    ('MNT', 1, 'Elaborar y ejecutar programas de mantenimiento preventivo.', 'M', 'RR', 'Presenta el programa de mantenimiento del edificio del año y su avance con las actividades registradas.'),
    ('MNT', 2, 'Diagnosticar y atender fallas básicas de infraestructura y servicios.', 'M', 'EP', 'Ante una falla real o simulada (fuga, apagador, bomba), identifica la causa probable y decide si la atiende o la escala.'),
    ('MNT', 3, 'Realizar reparaciones eléctricas menores dentro del alcance autorizado.', 'M', 'OD', 'Realiza una reparación eléctrica menor dentro de su alcance, con el circuito desenergizado y señalizado.'),
    ('MNT', 4, 'Realizar reparaciones hidráulicas y sanitarias menores.', 'M', 'OD', 'Realiza una reparación hidráulica o sanitaria menor sin dejar fugas ni contaminar el área.'),
    ('MNT', 5, 'Ejecutar trabajos básicos de pintura, carpintería, herrería y albañilería.', 'B', 'OD', 'Ejecuta un trabajo básico de pintura, carpintería, herrería o albañilería con acabado aceptable y área protegida.'),
    ('MNT', 6, 'Inspeccionar instalaciones y detectar condiciones inseguras.', 'M', 'OD', 'Hace un recorrido e identifica y reporta condiciones inseguras de instalaciones.'),
    ('MNT', 7, 'Clasificar solicitudes según urgencia, riesgo e impacto operativo.', 'M', 'OD', 'Ordena por urgencia e impacto un lote de solicitudes de mantenimiento correctivo y justifica la prioridad.'),
    ('MNT', 8, 'Aplicar medidas de bloqueo, señalización y control de acceso.', 'M', 'OD', 'Delimita, señaliza y restringe el acceso a un área antes de intervenir.'),
    ('MNT', 9, 'Utilizar herramientas y equipo de protección personal de forma segura.', 'M', 'OD', 'Selecciona la herramienta y el equipo de protección personal adecuados y los usa de forma segura.'),
    ('MNT', 10, 'Controlar proveedores y verificar reportes de servicio.', 'M', 'RR', 'Registra el ingreso de un proveedor, supervisa su trabajo y revisa su reporte de servicio antes de aceptarlo.'),
    ('MNT', 11, 'Documentar actividades, hallazgos, refacciones y liberación de áreas.', 'M', 'RR', 'Documenta una intervención con hallazgos, refacciones y la liberación del área por su responsable.'),
    ('MNT', 12, 'Mantener inventario y control de herramientas y materiales.', 'B', 'RR', 'Muestra el control de herramientas y materiales con entradas, salidas, préstamos y devoluciones.'),
    ('MNT', 13, 'Participar en planes de contingencia y continuidad operativa.', 'A', 'OD', 'Ante un corte de energía o falla de clima simulados, aplica las acciones de contención y avisa a los responsables.'),
    ('MNT', 14, 'Identificar riesgos de contaminación y proteger las áreas durante una intervención.', 'A', 'OD', 'Antes de intervenir en un área técnica, protege muestras, reactivos y superficies para evitar contaminación.'),
    ('MNT', 15, 'Manejar hojas de cálculo, correo electrónico y sistemas institucionales para registrar solicitudes y actividades.', 'B', 'EP', 'Registra solicitudes y actividades en hoja de cálculo, correo o sistema institucional.'),
    ('MNT', 16, 'Analizar fallas repetitivas y proponer acciones de mejora.', 'M', 'EP', 'Analiza fallas repetidas de un servicio y propone una acción para evitar que se repitan.'),
    ('RA', 1, 'Interpretación y aplicación de la norma ISO 15189:2022.', 'B', 'RR', 'Trata la solicitud aceptada como un acuerdo con el paciente: revisa antes de aceptar y registra cualquier cambio como modificación con ajuste en el recibo.'),
    ('RA', 2, 'Recepción e identificación de pacientes.', 'A', 'OD', 'Busca con las tres primeras letras, corrobora en voz alta fecha de nacimiento y teléfono, pide deletrear nombres poco comunes y muestra la etiqueta al paciente.'),
    ('RA', 3, 'Registro y verificación de información en sistemas informáticos.', 'A', 'OD', 'Captura médico, estudios (incluso el reverso de la orden) y tiempo de entrega; pregunta si autoriza el envío de resultados al correo del médico y anota la negativa en observaciones.'),
    ('RA', 4, 'Programación y control de citas.', 'M', 'OD', 'En simulación de llamada agenda una toma a domicilio: pregunta el día y el número de pacientes, consulta la colonia y ofrece horario según la zona.'),
    ('RA', 5, 'Facturación y manejo de efectivo.', 'B', 'RR', 'Verifica observaciones de la visita y datos fiscales antes de facturar, y realiza el corte de caja del día.'),
    ('RA', 6, 'Gestión y entrega de resultados.', 'A', 'OD', 'Pide el Recibo, verifica que el resultado esté VALIDADA, coteja nombre y folio en sobre, recibo y factura, sella de entregado con iniciales y fecha, y da de baja en XLAB.'),
    ('RA', 7, 'Control documental y trazabilidad de registros.', 'M', 'RR', 'Coteja la Bitácora del día contra el Recibo de cada paciente y actualiza las bitácoras al recibir muestras pendientes.'),
    ('RA', 8, 'Atención y orientación al paciente.', 'M', 'OD', 'Sigue las reglas de atención (saludo, identificar necesidades, información, despedida) y no interpreta resultados ni sugiere estudios sin orden médica.'),
    ('RA', 9, 'Manejo de sistemas informáticos de laboratorio.', 'M', 'OD', 'Recibe una muestra pendiente en el módulo RECEPCIÓN: da de baja la muestra, actualiza la fecha de entrega y reimprime el Recibo y, si es sanguínea, etiquetas y Carta de consentimiento.'),
    ('RA', 10, 'Aplicación de procedimientos del Sistema de Gestión de Calidad.', 'M', 'OD', 'Ante una queja presencial la escribe textual en el reporte y la remite al Coordinador del Sistema de Gestión de la Calidad antes de terminar su jornada.'),
    ('RA', 11, 'Protección de datos personales y confidencialidad de la información.', 'A', 'OD', 'Corrobora las pruebas con tono moderado y entrega resultados de carácter sensible sólo a quien el manual autoriza.'),
    ('REE', 1, 'Conocimiento y aplicación de los procedimientos del Sistema de Gestión de la Calidad relacionados con su proceso.', 'M', 'RR', 'Sigue la secuencia del numeral 16 del manual y la del TOX-PRC-001 Procedimiento de alta de pacientes en el sistema X-LAB para ETDDA en eventos de toxicología.'),
    ('REE', 2, 'Recepción, identificación y registro de pacientes conforme a los procedimientos institucionales.', 'A', 'OD', 'Coteja identificación oficial, pide confirmar nombre y fecha de nacimiento, localiza al paciente en XLAB Móvil y captura apellidos, nombre, fecha de nacimiento y sexo.'),
    ('REE', 3, 'Atención y servicio al paciente.', 'M', 'OD', 'Recibe y orienta con las reglas de atención del manual y favorece el flujo de pacientes del evento.'),
    ('REE', 4, 'Manejo del Sistema de Información del Laboratorio (LIS) y de las aplicaciones autorizadas por la empresa.', 'A', 'OD', 'Importa el contrato activo, configura etiquetas una sola vez, genera la lista de atendidos al final y exporta el archivo a USB.'),
    ('REE', 5, 'Conocimiento y aplicación de la cadena de custodia para las pruebas que así lo requieran.', 'A', 'OD', 'Imprime Recibo, TOX-REG-001 Evaluación toxicológica- Autorización, cuestionario de ingesta de medicamentos o tratamientos previos y etiquetas, verifica que coincidan con la identificación y entrega todo al custodio en tránsito.'),
    ('REE', 6, 'Protección de datos personales y confidencialidad de la información.', 'A', 'OD', 'Resguarda identificaciones y formatos y entrega la relación de pacientes atendidos sólo al representante autorizado del cliente y al Coordinador de Servicios Especiales.'),
    ('REE', 7, 'Control de registros y trazabilidad de la información.', 'M', 'RR', 'Los Recibos y TOX-REG-001 Evaluación toxicológica- Autorización, cuestionario de ingesta de medicamentos o tratamientos previos del evento están completos, con firma y huella, y la lista de atendidos concuerda con lo exportado.'),
    ('REE', 8, 'Manejo de equipo de cómputo y paquetería informática básica.', 'B', 'OD', 'Instala y retira la laptop e impresoras del evento e imprime formatos y etiquetas sin errores.'),
    ('RAND', 1, 'Interpretación y aplicación de la Norma ISO 15189:2022, en los requisitos relacionados con las actividades del área de Andrología.', 'M', 'OD', 'Relaciona situaciones del área (muestra incompleta, resultado atribuido a otro paciente) con el trabajo no conforme y la información al usuario, como lo aplica el laboratorio.'),
    ('RAND', 2, 'Conocimiento y aplicación del Manual de la OMS para el examen y procesamiento del semen humano, en su edición vigente.', 'A', 'OD', 'Explica las condiciones de recolección y manejo que el laboratorio toma de la OMS (abstinencia, muestra completa, 37 °C, inicio antes de 60 minutos); la técnica analítica no tiene procedimiento emitido.'),
    ('RAND', 3, 'Procesamiento, evaluación e interpretación de estudios de Andrología conforme a los procedimientos y métodos implementados por el laboratorio.', 'A', 'OD', 'Procesa una espermatobioscopia y compara su resultado con el de una muestra o video previamente analizado; el evaluador fija antes el criterio de concordancia porque no hay procedimiento técnico emitido.'),
    ('RAND', 4, 'Evaluación de la concentración, movilidad, vitalidad, morfología y demás parámetros seminales aplicables.', 'A', 'OD', 'Mide concentración, movilidad, vitalidad y morfología sobre muestras o material de referencia de valor conocido.'),
    ('RAND', 5, 'Identificación de condiciones preanalíticas, analíticas y postanalíticas que puedan afectar la calidad o validez de los resultados.', 'A', 'OD', 'Identifica en casos simulados abstinencia fuera de rango, muestra incompleta, uso de condón, demora mayor de 60 minutos o temperatura inadecuada.'),
    ('RAND', 6, 'Aplicación de criterios de aceptación, rechazo, conservación, procesamiento y trazabilidad de las muestras.', 'A', 'OD', 'Al recibir, anota hora de recolección, tiempo de licuefacción e integridad, coteja las muestras resguardadas en baño María contra la bitácora y rechaza muestras incompletas.'),
    ('RAND', 7, 'Control de calidad y aseguramiento de la validez de los resultados.', 'A', 'RR', 'Explica cómo asegura la validez de sus resultados; no hay control interno ni evaluación externa documentados para Andrología en los documentos emitidos.'),
    ('RAND', 8, 'Validación técnica, liberación y revisión de resultados del área de Andrología.', 'A', 'RR', 'Valida y reporta oportunamente y verifica al final del turno, con la bitácora, que todas las muestras recibidas se procesaron o quedaron documentadas.'),
    ('RAND', 9, 'Identificación y gestión de desviaciones, resultados atípicos, trabajo no conforme y no conformidades.', 'A', 'OD', 'Ante un resultado atribuido al paciente equivocado, detiene, informa, determina alcance, gestiona la corrección del informe y documenta.'),
    ('RAND', 10, 'Gestión de riesgos aplicada a las actividades del área.', 'M', 'OD', 'Contrasta un evento del área con la matriz de riesgos e indica si el control previsto funcionó.'),
    ('RAND', 11, 'Bioseguridad, manejo de RPBI y prevención de riesgos ocupacionales.', 'M', 'OD', 'Usa el equipo de protección, maneja el semen como material potencialmente infeccioso y da la disposición final el mismo día en el área de lavado de material.'),
    ('RAND', 12, 'Gestión documental, control de registros y mantenimiento de la trazabilidad de la información.', 'M', 'RR', 'Registra e integra la bitácora de trabajo y los registros analíticos en tiempo y forma.'),
    ('RAND', 13, 'Supervisión técnica, evaluación del desempeño y apoyo en la capacitación del personal asignado al área.', 'B', 'RR', 'Supervisa al personal asignado y documenta hallazgos y necesidades de capacitación.'),
    ('RAND', 14, 'Participación en auditorías internas, revisión de hallazgos e implementación de acciones correctivas y de mejora.', 'B', 'RR', 'Explica un hallazgo del área y la acción correctiva implementada, con su evidencia.'),
    ('RAND', 15, 'Manejo de Microsoft Office, Sistema de Información del Laboratorio y demás herramientas informáticas institucionales.', 'M', 'OD', 'Agenda y consulta citas de Andrología en XLab y captura y libera resultados.'),
    ('RHEM', 1, 'Interpretación de estudios hematológicos.', 'A', 'OD', 'Con biometrías hemáticas previamente analizadas, revisa antecedentes en XLab ante valores fuera de rango, repite la muestra cuando no hay antecedente de menos de un año, marca el valor verificado con asterisco y (V) y reconoce las interferencias del procedimiento (microcoágulos, hemólisis, aglutininas frías, agregados por EDTA).'),
    ('RHEM', 2, 'Interpretación de estudios de coagulación.', 'A', 'OD', 'Aplica las reglas de reporte del TP (100 % de actividad e INR, ajuste a 7.5 segundos, repetición con variación no mayor de 2 décimas, reporte del menor valor), hace la verificación manual de tiempos mayores de 100 segundos y registra el resultado.'),
    ('RHEM', 3, 'Evaluación microscópica de frotis sanguíneos.', 'A', 'OD', 'Lee los conteos celulares de las laminillas, los anota en la tarjeta de resultados, captura las observaciones morfológicas en XLab y coteja que lo impreso sea igual a lo capturado en AMS antes de validar; la concordancia se juzga contra la lectura de referencia de las laminillas previamente analizadas.'),
    ('RHEM', 4, 'Validación técnica y autorización para la liberación de resultados.', 'A', 'OD', 'No libera pacientes sin corrida aceptada y validada, coteja datos impresos contra capturados, transfiere de AMS a XLab, anota en la bitácora y decide liberación total o parcial cuando hay críticos pendientes.'),
    ('RHEM', 5, 'Interpretación de valores de alerta críticos.', 'A', 'OD', 'Ante casos simulados (plaquetas menores de 30.0 x10³/µL, INR mayor a 4.5, TTPa mayor de 85.0 segundos) verifica la integridad del proceso, repite, comunica a validación y llena todos los campos de la notificación, incluido el escalamiento cada hora hasta 4 horas.'),
    ('RHEM', 6, 'Control estadístico de la calidad y aplicación de las reglas de Westgard.', 'A', 'OD', 'Procesa los tres niveles TESTpoint y los dos niveles de coagulación, interpreta la gráfica de Levey-Jennings en Unity Real Time, distingue la regla de aviso 12s de las de rechazo 13s, 22s, R4s, 41s y 10x, y no procesa pacientes hasta aceptar la corrida.'),
    ('RHEM', 7, 'Manejo de analizadores hematológicos y de coagulación.', 'A', 'OD', 'Ejecuta el arranque y mantenimiento diario del ADVIA 120 (conteo de fondo dentro de parámetros) y el arranque del BFT II (calentamiento a 37.4 °C, autoajuste, cubetas con agitador), y documenta la actividad.'),
    ('RHEM', 8, 'Evaluación del desempeño analítico.', 'M', 'RR', 'Calcula e interpreta media, desviación estándar y coeficiente de variación del control interno, los compara con la especificación de calidad del mensurando y lee el informe del ensayo de aptitud PACAL como evidencia de veracidad.'),
    ('RHEM', 9, 'Gestión de equipos, calibración y verificación.', 'M', 'OD', 'Identifica cuándo calibrar (ADVIA 120: instalación, mantenimiento preventivo, cambio significativo del control; BFT II: lote nuevo de Innovin) y, ante una falla simulada, detiene el uso, identifica el equipo como fuera de servicio y registra el incidente.'),
    ('RHEM', 10, 'Gestión documental.', 'M', 'RR', 'Trabaja con documentos vigentes, registra de forma clara, legible, íntegra y trazable, y mantiene accesibles las fichas de datos de seguridad de los reactivos del área.'),
    ('RHEM', 11, 'Gestión de riesgos.', 'M', 'OD', 'Ante un evento del área (muestra con coágulo, proporción sangre/anticoagulante incorrecta, reactivo fuera de estabilidad) indica si el riesgo está en la matriz y si el control previsto funcionó.'),
    ('RHEM', 12, 'Investigación de desviaciones y análisis de causa raíz.', 'A', 'OD', 'Ante un control rechazado o un resultado PACAL no satisfactorio, detiene y retiene, determina el alcance desde el último control aceptable, registra el trabajo no conforme y documenta la causa raíz aparte, enlazada por folio.'),
    ('RHEM', 13, 'Interpretación y aplicación de la norma ISO 15189:2022.', 'M', 'OD', 'Relaciona situaciones reales del área con los requisitos que las rigen: trabajo no conforme (7.5), notificación de resultados críticos (7.4.1) y aseguramiento de la validez de los resultados (7.3.7), tal como los aplican los procedimientos del laboratorio.'),
    ('RIES', 1, 'Interpretación y aplicación de los requisitos de la Norma ISO 15189:2022 y de los procedimientos del Sistema de Gestión de la Calidad.', 'M', 'OD', 'Relaciona casos del área (control fuera, PEA no satisfactorio, incertidumbre excedida) con el procedimiento y registro que los atienden.'),
    ('RIES', 2, 'Supervisión y, cuando las necesidades operativas lo requieran, operación de los analizadores y sistemas analíticos del área de Inmunología Especial.', 'A', 'OD', 'Carga un reactivo nuevo resuspendiendo micropartículas 30 veces, coloca septos y calibra al cambio de lote; registra el mantenimiento diario.'),
    ('RIES', 3, 'Validación, verificación, autorización y liberación de resultados conforme a las competencias y autorizaciones vigentes.', 'A', 'RR', 'Comprueba en bitácoras la verificación de resultados con diferencia mayor de 20 % contra la visita anterior y el reproceso dentro de 5 % antes de liberar.'),
    ('RIES', 4, 'Interpretación técnica de los inmunoensayos y evaluación de la consistencia de los resultados.', 'A', 'OD', 'Ante resultados de TSH, β-hCG o estradiol explica si son de notificación inmediata y la dilución aplicable cuando exceden el intervalo.'),
    ('RIES', 5, 'Supervisión de la aplicación, interpretación y seguimiento del Control de Calidad Interno.', 'A', 'RR', 'Revisa que los controles se procesaron antes de pacientes cada día de uso y que los rechazos tienen acción documentada.'),
    ('RIES', 6, 'Interpretación de las gráficas de Levey-Jennings y aplicación de las reglas de Westgard para la toma de decisiones técnicas.', 'A', 'OD', 'Decide sobre una corrida con regla violada: contener, investigar material, reactivo y calibración, y reanalizar pacientes desde el último control aceptable.'),
    ('RIES', 7, 'Coordinación y evaluación de la participación del área en los Programas de Evaluación Externa de la Calidad.', 'A', 'RR', 'Revisa la recepción, manejo, proceso antes del día 21 y captura de la muestra PEA de inmunología, y su resultado.'),
    ('RIES', 8, 'Gestión, evaluación y seguimiento de resultados críticos, resultados inconsistentes y desviaciones analíticas.', 'A', 'SI', 'Simula la notificación de una TSH crítica: confirma sistema, histórico e integridad de muestra, se identifica, identifica al receptor, transmite y registra el escalamiento.'),
    ('RIES', 9, 'Verificación de métodos de examen y evaluación de su desempeño, conforme a los procedimientos establecidos.', 'A', 'RR', 'Presenta la verificación de un inmunoensayo del área con su declaración de cumplimiento.'),
    ('RIES', 10, 'Evaluación de la incertidumbre de la medición, cuando aplique.', 'M', 'RR', 'Calcula el error cuadrático medio de un analito con al menos seis meses de control interno y el sesgo de la evaluación externa, y lo compara contra su máximo permitido.'),
    ('RIES', 11, 'Identificación, evaluación y gestión de riesgos asociados al proceso analítico.', 'M', 'OD', 'Explica los riesgos del área en la matriz y el plan de continuidad ante falla de analizador.'),
    ('RIES', 12, 'Investigación de desviaciones, incidentes, trabajo no conforme, no conformidades y análisis de causa raíz, así como implementación y seguimiento de acciones correctivas.', 'A', 'OD', 'Documenta un trabajo no conforme con alcance, significado clínico, decisión y enlace por folio a la causa raíz.'),
    ('RIES', 13, 'Supervisión de la operación, verificación y gestión del mantenimiento de los equipos analíticos e instrumentos de medición del área.', 'M', 'RR', 'Revisa el cumplimiento del programa de calibración y mantenimiento de los equipos del área y el manejo de fallas.'),
    ('RIES', 14, 'Gestión documental, control de registros y aseguramiento de la trazabilidad de muestras, resultados e información conforme al Sistema de Gestión de la Calidad.', 'M', 'RR', 'Verifica el resguardo de muestras del área (3 días en refrigerador, 6 en congelador) y la trazabilidad de bitácoras.'),
    ('RIES', 15, 'Manejo del Sistema de Información del Laboratorio (SIL, LIS, XLAB u otros autorizados).', 'M', 'OD', 'Libera en el sistema dentro de su autorización y registra altas y bajas en XLAB Inventario.'),
    ('RIES', 16, 'Aplicación de los requisitos de bioseguridad, seguridad e higiene y manejo de RPBI.', 'M', 'OD', 'Manipula reactivos con bata, guantes y lentes, y supervisa la disposición de RPBI del área.'),
    ('RIRU', 1, 'Ejecución e interpretación de pruebas serológicas e inmunológicas de rutina.', 'A', 'OD', 'Procesa muestras caracterizadas positivas y negativas con sus controles positivo y negativo del fabricante en cada corrida, y su clasificación concuerda. Los criterios de lectura e interpretación salen del inserto de cada método, porque no hay procedimiento de examen de Inmunología Rutinaria emitido.'),
    ('RIRU', 2, 'Aplicación de criterios de reactividad, confirmación y repetición.', 'A', 'OD', 'Ante resultados reactivos, limítrofes o discrepantes, aplica la repetición por duplicado y el envío a confirmatoria que indica su descripción de puesto; los criterios de reactividad y zona gris se toman del inserto del método, porque ningún procedimiento emitido los define.'),
    ('RIRU', 3, 'Operación y verificación de equipos de inmunoensayo.', 'M', 'OD', 'Verifica que reactivos alcancen la temperatura de trabajo, controla tiempos de incubación y registra temperaturas de refrigeradores e incubadoras.'),
    ('RIRU', 4, 'Manejo confidencial de resultados sensibles.', 'A', 'OD', 'Explica cómo se resguarda un resultado sensible y su consentimiento; el procedimiento especial de notificación que cita su descripción de puesto no está desarrollado en un documento emitido.'),
    ('RIRU', 5, 'Aplicación e interpretación del control estadístico de la calidad (reglas de Westgard, gráficos de Levey-Jennings).', 'A', 'OD', 'Ante una serie de gráficos de Levey-Jennings del área, identifica la regla violada según las reglas asignadas por sigma, contiene el error interrumpiendo pacientes, no elimina el punto rechazado y define qué pacientes reanalizar desde el último evento en control.'),
    ('RIRU', 6, 'Validación técnica y liberación de resultados.', 'A', 'RR', 'En bitácoras recientes del colaborador, comprueba que los resultados en verificación llevan (*) y (*v), que los liberados llevan (LIB) con iniciales, y que la diferencia entre primer resultado y reproceso no excedió el 5 %.'),
    ('RIRU', 7, 'Verificación del desempeño de métodos y equipos analíticos.', 'A', 'RR', 'Explica y revisa un estudio de verificación del área: réplicas de precisión, criterio de 0,25 o 0,33 del error total, linealidad con puntos de decisión clínica, y la acción cuando un criterio no se cumple.'),
    ('RIRU', 8, 'Trazabilidad metrológica y manejo de materiales de referencia.', 'M', 'RR', 'Localiza la carta de trazabilidad de un analito del alcance, identifica el material de referencia de mayor orden y su incertidumbre, y explica cuándo es aceptable la trazabilidad declarada por el fabricante.'),
    ('RIRU', 9, 'Investigación de desviaciones, trabajo no conforme y análisis de causa raíz.', 'A', 'OD', 'Sobre un caso de control fuera de criterio, aplica detener y retener, determina el alcance desde el último punto bajo control, gradúa el significado clínico, documenta el evento y enlaza la causa raíz por folio.'),
    ('RIRU', 10, 'Gestión documental y control de registros.', 'M', 'RR', 'Verifica que los registros del área que llena el colaborador estén completos, legibles y trazables, en su versión vigente, y que las correcciones conservan el dato original.'),
    ('RIRU', 11, 'Gestión de riesgos aplicada al proceso analítico.', 'M', 'OD', 'Ubica en la matriz los riesgos del área a su cargo y explica los controles vigentes, y propone el registro de un riesgo nuevo detectado en un caso de falla de equipo o desabasto.'),
    ('RIRU', 12, 'Manejo del sistema de información del laboratorio.', 'M', 'OD', 'Ejecuta en X-Lab y AMS la revisión de resultados, el envío a verificación (reanálisis) y la liberación por analito o por paciente, con su usuario y contraseña.'),
    ('RMIC', 1, 'Cultivo, aislamiento e identificación de microorganismos.', 'A', 'OD', 'Siembra, incuba, lee e identifica sobre muestras previamente caracterizadas; la concordancia se juzga contra la identificación de referencia. No hay procedimiento técnico emitido que fije medios, tiempos ni criterios de lectura.'),
    ('RMIC', 2, 'Realización e interpretación de tinciones y pruebas bioquímicas.', 'A', 'OD', 'Prepara e interpreta tinciones y pruebas bioquímicas de identificación sobre cepas o laminillas de resultado conocido.'),
    ('RMIC', 3, 'Ejecución e interpretación de pruebas de susceptibilidad antimicrobiana.', 'A', 'OD', 'Ejecuta e interpreta la susceptibilidad de una cepa de resultado conocido con los criterios vigentes que el laboratorio declare; no hay documento emitido que diga qué versión de criterios se aplica.'),
    ('RMIC', 4, 'Control de calidad con cepas de referencia y manejo de cepario.', 'A', 'OD', 'Resiembra y conserva cepas de referencia y realiza el control de medios y discos con ellas, documentando lote y resultado.'),
    ('RMIC', 5, 'Operación y verificación de campana de bioseguridad, incubadoras y autoclave.', 'A', 'OD', 'Verifica y registra la temperatura de incubadoras, refrigeradores y congeladores y el funcionamiento de campana y autoclave; ante una falla detiene el uso, etiqueta el equipo y registra el incidente.'),
    ('RMIC', 6, 'Aplicación e interpretación del control estadístico de la calidad (reglas de Westgard, gráficos de Levey-Jennings).', 'M', 'OD', 'Interpreta gráficas de Levey-Jennings y reglas de Westgard en los casos en que el área tenga mediciones cuantitativas; para lo cualitativo explica que los criterios de control deben estar en el procedimiento de examen.'),
    ('RMIC', 7, 'Validación técnica y liberación de resultados.', 'A', 'RR', 'Confirma resultados anormales o discrepantes antes de liberar, verifica la notificación de críticos y libera en el sistema informático.'),
    ('RMIC', 8, 'Verificación del desempeño de métodos y equipos analíticos.', 'M', 'RR', 'Explica y documenta la verificación del método cualitativo antes de su uso y la verificación de desempeño al cambio de lote de reactivos y medios.'),
    ('RMIC', 9, 'Trazabilidad metrológica y manejo de materiales de referencia.', 'M', 'RR', 'Localiza la evidencia de trazabilidad de los materiales de referencia y equipos del área y explica qué parte de la cadena controla el laboratorio.'),
    ('RMIC', 10, 'Investigación de desviaciones, trabajo no conforme y análisis de causa raíz.', 'A', 'OD', 'Ante un caso (incubadora fuera de temperatura, cultivo mal identificado) detiene, determina el alcance desde el último punto bajo control, gradúa el significado clínico y documenta el evento y la causa raíz en sus registros.'),
    ('RMIC', 11, 'Gestión documental y control de registros.', 'M', 'RR', 'Trabaja con documentos vigentes y llena los registros del área de forma legible, íntegra y trazable.'),
    ('RMIC', 12, 'Gestión de riesgos aplicada al proceso analítico.', 'M', 'OD', 'Contrasta un evento del área con la matriz de riesgos e indica si el riesgo estaba identificado y si el control previsto funcionó.'),
    ('RMIC', 13, 'Manejo del sistema de información del laboratorio.', 'M', 'OD', 'Registra, valida y libera resultados en XLab sin errores de captura y consulta antecedentes del paciente.'),
    ('RPAR', 1, 'Examen macroscópico y microscópico de muestras coproparasitoscópicas.', 'A', 'OD', 'Verifica consistencia, tiempo desde la emisión y número de muestra de la serie antes de procesar; realiza el examen directo y reporta sobre muestras o laminillas de resultado conocido.'),
    ('RPAR', 2, 'Aplicación de métodos de concentración y tinciones.', 'A', 'OD', 'Ejecuta los métodos de concentración y las tinciones del área; no hay procedimiento técnico emitido que los describa, por lo que el evaluador debe fijar antes el método de referencia.'),
    ('RPAR', 3, 'Identificación morfológica de parásitos y sus estadios evolutivos.', 'A', 'OD', 'Identifica parásitos y estadio (trofozoíto, quiste, huevecillo) en laminillas o imágenes control; confirma positivos o dudosos con segunda lectura.'),
    ('RPAR', 4, 'Preparación y control de reactivos y colorantes.', 'M', 'OD', 'Prepara, identifica y verifica vigencia y condiciones de reactivos, colorantes y soluciones de concentración, y los libera al cambio de lote.'),
    ('RPAR', 5, 'Aplicación e interpretación del control estadístico de la calidad (reglas de Westgard, gráficos de Levey-Jennings).', 'B', 'OD', 'Explica las reglas de Westgard y su ámbito (mediciones cuantitativas) y dónde deben definirse los criterios de control de un método cualitativo.'),
    ('RPAR', 6, 'Validación técnica y liberación de resultados.', 'A', 'RR', 'Confirma resultados positivos, discrepantes o dudosos antes de liberar y libera en el sistema informático.'),
    ('RPAR', 7, 'Verificación del desempeño de métodos y equipos analíticos.', 'M', 'RR', 'Explica la verificación de un método cualitativo antes de su uso y revisa el estado de microscopio y centrífuga del área.'),
    ('RPAR', 8, 'Trazabilidad metrológica y manejo de materiales de referencia.', 'B', 'RR', 'Localiza y mantiene el material de referencia morfológica (atlas, laminillas control, imágenes).'),
    ('RPAR', 9, 'Investigación de desviaciones, trabajo no conforme y análisis de causa raíz.', 'A', 'OD', 'Ante una muestra recibida fuera de tiempo o un falso negativo detectado en ensayo de aptitud, detiene, determina alcance, gradúa el significado clínico y documenta.'),
    ('RPAR', 10, 'Gestión documental y control de registros.', 'M', 'RR', 'Usa documentos vigentes y llena los registros del área de forma legible, íntegra y trazable.'),
    ('RPAR', 11, 'Gestión de riesgos aplicada al proceso analítico.', 'M', 'OD', 'Identifica el riesgo de una muestra seriada mal identificada o fuera de tiempo y lo contrasta con la matriz.'),
    ('RPAR', 12, 'Manejo del sistema de información del laboratorio.', 'M', 'OD', 'Imprime y actualiza la bitácora del área en XLab, coteja muestras físicas contra la bitácora y libera resultados.'),
    ('RQC', 1, 'Interpretación técnica de pruebas de Química Clínica.', 'A', 'OD', 'Ante resultados de química clínica (glucosa en muestra tardía, potasio crítico, dilución fuera de límite) explica la interferencia o conducta que fija el procedimiento de examen.'),
    ('RQC', 2, 'Validación técnica y autorización de resultados.', 'A', 'RR', 'En bitácoras del área comprueba la verificación y el reproceso dentro de 5 %, y que los críticos se confirmaron y notificaron con registro.'),
    ('RQC', 3, 'Aplicación e interpretación de las reglas de Westgard.', 'A', 'OD', 'Asigna las reglas de un analito según su sigma con dos niveles de control y aplica la conducta ante el rechazo.'),
    ('RQC', 4, 'Control estadístico de la calidad.', 'A', 'RR', 'Revisa el seguimiento mensual del desempeño de los analitos (CV, sesgo, sigma) y el registro diario de controles.'),
    ('RQC', 5, 'Manejo, operación y verificación de analizadores automatizados de Química Clínica.', 'A', 'OD', 'Calibra al cambio de lote de reactivo, reposa cartuchos 4 horas en vertical, verifica estabilidad a bordo y registra el mantenimiento diario.'),
    ('RQC', 6, 'Verificación y validación de métodos de examen.', 'A', 'RR', 'Presenta la verificación de un analito: linealidad con 5 niveles por triplicado, precisión con 20 réplicas, veracidad y su conclusión.'),
    ('RQC', 7, 'Gestión documental.', 'M', 'RR', 'La documentación del área está vigente y controlada, y los registros de control, temperatura y condiciones ambientales están al día.'),
    ('RQC', 8, 'Gestión de riesgos.', 'M', 'OD', 'Explica los riesgos del área registrados en la matriz y el plan de continuidad ante falla de equipo o escasez de reactivos.'),
    ('RQC', 9, 'Investigación y análisis de desviaciones, incidentes y no conformidades.', 'A', 'OD', 'Investiga un resultado PACAL no satisfactorio: evaluación de impacto clínico, causa raíz y seguimiento de acciones.'),
    ('RQC', 10, 'Evaluación del desempeño analítico.', 'A', 'RR', 'Revisa el cumplimiento de las especificaciones de calidad y la incertidumbre del área contra su máximo permitido.'),
    ('RSUB', 1, 'Selección, evaluación y seguimiento del desempeño de laboratorios de referencia.', 'M', 'RR', 'Aplica los registros de evaluación, seguimiento y reevaluación y propone continuidad, suspensión o baja con base en sus resultados.'),
    ('RSUB', 2, 'Verificación de requisitos de muestra por tipo de estudio subrogado.', 'A', 'OD', 'Coteja en Xlab plus el tipo y cantidad de muestra y el laboratorio destino, y verifica recipiente, volumen, identificación y conservación antes de almacenar o enviar; ante discrepancia suspende el envío.'),
    ('RSUB', 3, 'Alicuotado, identificación y embalaje de muestras biológicas.', 'A', 'OD', 'Coloca PARAFILM, bolsa individual con su requisición, recipiente secundario con refrigerante, sella con cinta y etiqueta remitente y destinatario.'),
    ('RSUB', 4, 'Control de cadena de frío y de condiciones de transporte.', 'A', 'RR', 'Registra temperaturas de refrigerador, congelador y ambiente al inicio, a media y al final de la jornada en el área de subrogación.'),
    ('RSUB', 5, 'Integración y verificación de informes de laboratorios externos.', 'A', 'RR', 'Coteja datos del paciente, prueba, metodología y valores de referencia, anota laboratorio, fecha e iniciales, y anexa el original para su validación.'),
    ('RSUB', 6, 'Documentación de incidencias y análisis de causa raíz.', 'M', 'OD', 'Ante un rechazo del laboratorio de referencia evalúa estabilidad y alternativas, levanta la incidencia o no conformidad y notifica al Coordinador de Procedimientos Analíticos.'),
    ('RSUB', 7, 'Manejo de sistemas informáticos y plataformas de laboratorios de referencia.', 'M', 'OD', 'Registra en el PANEL DE SERVICIOS SUBROGADOS las acciones ENVIAR, NOTIFICAR, RECIBIR, REPORTE RESULTADO y VALIDAR por folio, y rastrea el paquete.'),
    ('RSUB', 8, 'Control de registros y trazabilidad documental.', 'M', 'RR', 'Conserva la evidencia de recepción del transportista o del laboratorio (guía, acuse) y llena las secciones que le tocan de la solicitud de pruebas nuevas.'),
    ('RTOX', 1, 'Interpretación y aplicación de la norma ISO 15189:2022.', 'B', 'OD', 'Explica por qué el área, aunque fuera del alcance de acreditación, sigue los procedimientos del sistema (trabajo no conforme, control interno, registros) y los relaciona con la norma.'),
    ('RTOX', 2, 'Aplicación y supervisión de la cadena de custodia de muestras.', 'A', 'OD', 'Verifica coincidencia de identificación oficial y etiquetas, firmas y huella, observación permanente, volumen de 100 a 120 mL, lectura de temperatura, sellado de contenedores y transferencia documentada de la custodia.'),
    ('RTOX', 3, 'Validación, verificación y liberación de resultados toxicológicos.', 'A', 'RR', 'Imprime resultados del VIVA-E, transcribe folio, iniciales y resultado en tinta azul, coloca la carpeta en la mesa de validación y verifica la transcripción de otro analista.'),
    ('RTOX', 4, 'Interpretación de resultados de pruebas para la detección de drogas de abuso y otras pruebas toxicológicas.', 'A', 'OD', 'Clasifica resultados de cocaína como positivos o negativos contra el punto de corte de 150 ng/mL y reconoce la reactividad cruzada con benzoilecgonina-glucurónido descrita en el procedimiento.'),
    ('RTOX', 5, 'Aplicación, interpretación y seguimiento del control de calidad interno.', 'A', 'OD', 'Procesa dos niveles de control con benzoilecgonina antes de las muestras, valida la calibración con los controles y recalibra cuando los controles salen de los límites.'),
    ('RTOX', 6, 'Participación, evaluación y seguimiento de los Programas de Evaluación Externa de la Calidad.', 'M', 'RR', 'Procesa la muestra del proveedor JAR QUALITY como muestra de rutina, registra resultado y método, captura dentro del periodo y documenta la causa raíz de un resultado no satisfactorio.'),
    ('RTOX', 7, 'Aplicación de criterios de aceptación y rechazo de muestras.', 'A', 'OD', 'Ante casos simulados decide: temperatura de 33 a 35 °C no válida, de 36 a 38 °C válida; sospecha de adulteración, no válida hasta acordar con el cliente; volumen insuficiente.'),
    ('RTOX', 8, 'Gestión documental, control de registros y trazabilidad de la información.', 'M', 'RR', 'Llena los registros de custodia, resguardo y resultados con trazabilidad completa y usa documentos vigentes.'),
    ('RTOX', 9, 'Identificación, evaluación y gestión de riesgos asociados al proceso analítico.', 'M', 'OD', 'Identifica riesgos de la custodia (identificación del donante, adulteración, sustitución, pérdida de trazabilidad) y los contrasta con la matriz.'),
    ('RTOX', 10, 'Operación, verificación y supervisión del mantenimiento de equipos analíticos.', 'A', 'OD', 'Arranca el VIVA-E, verifica que la unidad de refrigeración se estabilice 12 °C por debajo del ambiente, hace el mantenimiento diario y homogeneiza los reactivos sin burbujas.'),
    ('RTOX', 11, 'Investigación y seguimiento de desviaciones, incidentes y no conformidades.', 'A', 'OD', 'Ante una cadena de custodia interrumpida o una muestra con sospecha de adulteración, detiene, comunica, documenta el trabajo no conforme y la causa raíz.'),
    ('RTOX', 12, 'Supervisión técnica del personal y evaluación de la competencia.', 'M', 'RR', 'Supervisa al auxiliar en custodia y procesamiento, documenta hallazgos y solicita reevaluación cuando hay errores recurrentes.'),
    ('RURO', 1, 'Análisis físico, químico y microscópico de orina.', 'A', 'OD', 'Mide volumen, homogeneiza por inversión sin espuma, observa color en fondo blanco y aspecto en fondo oscuro, sumerge y seca la tira como indica el procedimiento, corrobora densidad por refractometría cuando aplica, centrifuga a 400 g 5 minutos y prepara 30 µL de sedimento.'),
    ('RURO', 2, 'Identificación de elementos formes en sedimento urinario.', 'A', 'OD', 'Identifica y gradúa leucocitos, eritrocitos, células, cilindros, cristales, levaduras y bacterias en 10 campos de 40x conforme a la guía de lectura, con concordancia frente a muestras de referencia o del PACAL.'),
    ('RURO', 3, 'Validación técnica de resultados.', 'A', 'RR', 'Confirma resultados anormales o inconsistentes, confirma bilirrubina positiva con Lugol o bilirrubina directa sérica, y libera en el sistema informático.'),
    ('RURO', 4, 'Aplicación e interpretación del control estadístico de calidad.', 'A', 'OD', 'Procesa control N y P antes del primer análisis, compara contra el inserto, valida en Unity Real Time, no procesa pacientes sin corrida liberada y, ante rechazo, evalúa pacientes desde el último control satisfactorio.'),
    ('RURO', 5, 'Gestión documental.', 'M', 'RR', 'Usa documentos vigentes y llena los registros del área de forma legible, íntegra y trazable.'),
    ('RURO', 6, 'Gestión de riesgos.', 'M', 'OD', 'Ante un evento (muestra de más de 2 horas, tiras expuestas a humedad, temperatura del área menor de 22 °C) indica el efecto sobre el resultado y si el riesgo está en la matriz.'),
    ('RURO', 7, 'Manejo, verificación y aseguramiento del desempeño de equipos analíticos.', 'A', 'OD', 'Opera el Clinitek Advantus (captura de ID y color, colocación de la tira), revisa condiciones ambientales del área y da mantenimiento al baño María según su instrucción.'),
    ('RURO', 8, 'Investigación de desviaciones, incidentes y análisis de causa raíz.', 'A', 'OD', 'Ante un control rechazado o un resultado PACAL no satisfactorio, detiene, determina el alcance, registra el trabajo no conforme y documenta la causa raíz enlazada por folio.'),
    ('RURO', 9, 'Interpretación de criterios de aceptación, rechazo y validación de resultados.', 'A', 'OD', 'Aplica a casos simulados los criterios de muestra (volumen de 10 mL adulto y 5 mL pediátrico, frasco estéril, tiempo de remisión) y los niveles de decisión clínica de la tabla del procedimiento.'),
    ('SGEN', 1, 'Ejecutar correctamente actividades de limpieza, sanitización y desinfección de instalaciones, mobiliario y áreas del laboratorio.', 'M', 'OD', 'Limpia y desinfecta un área asignada (sanitario, sala de espera o toma de muestras) con el producto y la técnica que corresponde y registra la actividad.'),
    ('SGEN', 2, 'Conocimiento y cumplimiento de normas de bioseguridad.', 'M', 'RR', 'Durante un recorrido cumple las medidas generales de bioseguridad (sin alimentos en áreas técnicas, EPP según el área, área ordenada).'),
    ('SGEN', 3, 'Utilizar correctamente el equipo de protección personal de acuerdo con las actividades realizadas.', 'A', 'OD', 'Se coloca guantes, bata, cubrebocas y protección ocular antes de manejar RPBI y los retira y desecha sin contaminarse.'),
    ('SGEN', 4, 'Manejar correctamente materiales, herramientas, productos químicos y equipos asignados para sus funciones.', 'M', 'OD', 'Usa sólo productos autorizados, respeta la etiqueta del producto y registra el préstamo y devolución de herramientas.'),
    ('SGEN', 5, 'Manejo seguro de residuos peligrosos (RPBI).', 'A', 'OD', 'Traslada el RPBI por la ruta interna al almacén temporal, en sus envases cerrados, y atiende la entrega al proveedor verificando envases y documentación.'),
    ('SGEN', 6, 'Seguimiento de procedimientos.', 'M', 'RR', 'Ejecuta las actividades del rol en la frecuencia programada y llena los registros correspondientes sin omisiones.'),
    ('SGEN', 7, 'Aplicación de procedimientos de limpieza y desinfección.', 'M', 'OD', 'Prepara una solución de hipoclorito a la concentración indicada a partir del producto comercial, conforme a la tabla de diluciones, y explica cuándo usar cada una.'),
    ('SGEN', 8, 'Identificación de riesgos biológicos, químicos y físicos.', 'M', 'OD', 'En un recorrido o caso, identifica condiciones inseguras (fuga, derrame, cable expuesto, contenedor lleno) y las reporta.'),
    ('SGEN', 9, 'Aplicación de medidas de bioseguridad y prevención de contaminación cruzada.', 'A', 'OD', 'Limpia de áreas limpias a sucias, cambia guantes entre áreas y no traslada utensilios de sanitarios a áreas de toma de muestra.'),
    ('SGEN', 10, 'Respuesta inicial ante derrames o condiciones inseguras.', 'A', 'OD', 'En un simulacro de derrame biológico suspende la actividad, restringe el área, avisa al Supervisor de Bioseguridad y aplica el kit antiderrame con hipoclorito al 1 %.'),
    ('SBIO', 1, 'Identificar peligros y evaluar riesgos de bioseguridad.', 'A', 'OD', 'En un recorrido por un área técnica identifica peligros biológicos, químicos y físicos y los valora con la metodología del laboratorio.'),
    ('SBIO', 2, 'Definir y verificar controles conforme a la jerarquía de control de riesgos. Supervisar prácticas seguras en las fases preanalítica, analítica y postanalítica.', 'A', 'OD', 'Propone el control que corresponde a un peligro siguiendo la jerarquía de control y verifica en el punto de uso que las prácticas seguras se aplican en las tres fases.'),
    ('SBIO', 3, 'Gestionar RPBI y verificar su trazabilidad documental.', 'A', 'RR', 'Verifica segregación, envase, llenado y almacenamiento temporal, y coteja la entrega al proveedor con manifiesto y bitácora.'),
    ('SBIO', 4, 'Seleccionar y supervisar el uso correcto del EPP.', 'A', 'OD', 'Elige el EPP para una actividad de riesgo y observa su colocación, retiro y desecho por el personal.'),
    ('SBIO', 5, 'Interpretar hojas de datos de seguridad y compatibilidad química.', 'A', 'OD', 'Con la hoja de datos de seguridad de un reactivo, identifica peligros, EPP, incompatibilidades y respuesta ante derrame.'),
    ('SBIO', 6, 'Coordinar la respuesta ante derrames, exposiciones y emergencias.', 'A', 'OD', 'En un derrame simulado restringe el área, usa el kit antiderrame, aplica hipoclorito al 1 % con el tiempo de contacto y notifica.'),
    ('SBIO', 7, 'Investigar incidentes y accidentes mediante análisis de causa.', 'A', 'OD', 'Investiga un accidente simulado, recaba evidencia, determina la causa y propone acciones proporcionales al riesgo.'),
    ('SBIO', 8, 'Elaborar programas, procedimientos, listas de verificación e informes.', 'M', 'RR', 'Elabora el informe periódico de bioseguridad con eventos, hallazgos, tendencias y necesidades de recursos.'),
    ('SBIO', 9, 'Impartir capacitación y evaluar su eficacia.', 'M', 'OD', 'Imparte un tema de bioseguridad, aplica la evaluación y analiza su eficacia.'),
    ('SBIO', 10, 'Planear y evaluar simulacros.', 'M', 'RR', 'Planea un simulacro, registra su resultado y define oportunidades de mejora con responsable.'),
    ('SBIO', 11, 'Analizar indicadores y tendencias de seguridad.', 'M', 'RR', 'Analiza la tendencia de accidentes, exposiciones y derrames del periodo e identifica recurrencias.'),
    ('SBIO', 12, 'Verificar equipos y materiales de emergencia dentro de su alcance.', 'A', 'OD', 'Revisa botiquín, lavaojos, regadera y kit antiderrame: ubicación, acceso, contenido y vigencia.'),
    ('SBIO', 13, 'Gestionar acciones correctivas y verificar su eficacia.', 'A', 'RR', 'Documenta una no conformidad de bioseguridad, da seguimiento a la acción correctiva y verifica que no haya recurrencia.'),
    ('SBIO', 14, 'Manejar hojas de cálculo, presentaciones y sistemas institucionales.', 'B', 'EP', 'Concentra en hoja de cálculo los eventos del periodo y presenta los resultados.'),
    ('SBIO', 15, 'Comunicar riesgos y medidas de control de manera clara y oportuna.', 'M', 'OD', 'Comunica al personal de un área un riesgo detectado y la medida de control, y verifica que se entendió.'),
    ('VTA', 1, 'Conocimiento de los requisitos del Sistema de Gestión de la Calidad aplicables a su puesto, conforme a la Norma ISO 15189:2022.', 'M', 'ES', 'Resuelve casos sobre confidencialidad, quejas, retroalimentación de usuarios y uso del símbolo de acreditación.'),
    ('VTA', 2, 'Conocimiento del portafolio de servicios, alcance de las pruebas, requisitos preanalíticos y condiciones generales de prestación de los servicios del laboratorio.', 'A', 'OD', 'Ante preguntas simuladas de un médico, consulta el catálogo vigente para la muestra, la preparación y el tiempo de entrega, y canaliza lo técnico al analista autorizado.'),
    ('VTA', 3, 'Conocimiento de las políticas comerciales y de atención al cliente del laboratorio.', 'A', 'OD', 'Ante una propuesta simulada de comisión por paciente enviado, la rechaza conforme al código de conducta y la reporta a su coordinador.'),
    ('VTA', 4, 'Técnicas de ventas consultivas, negociación, atención y servicio al cliente.', 'M', 'OD', 'En una visita acompañada, presenta los servicios con información institucional vigente y sin ofrecer asesoría clínica.'),
    ('VTA', 5, 'Manejo de Microsoft Office.', 'B', 'RR', 'Elabora y entrega en tiempo el reporte de ventas y seguimiento de médicos visitados en hoja de cálculo.'),
    ('VTA', 6, 'Manejo del Sistema de Información del Laboratorio (LIS) conforme a las funciones autorizadas para el puesto.', 'M', 'OD', 'Consulta en el sistema sólo la información que su perfil permite y con sus propias credenciales.'),
    ('VTA', 7, 'Elaboración de reportes de actividades, indicadores comerciales y seguimiento de clientes.', 'M', 'RR', 'Se revisan el plan y los reportes del periodo: completos, veraces y coherentes entre lo programado y lo visitado.'),
    ('VTA', 8, 'Conocimiento y aplicación de los procedimientos del Sistema de Gestión de la Calidad relacionados con su proceso.', 'M', 'RR', 'Se verifica que aplicó la retroalimentación a médicos y empresas y entregó lo recogido conforme al procedimiento.'),
    ('VTA', 9, 'Comunicación efectiva, relaciones institucionales y manejo profesional de clientes.', 'B', 'OD', 'Atiende de forma cordial y profesional a un cliente en una visita o un evento, y da seguimiento al compromiso acordado.'),
    ('VTA', 10, 'Conocimiento de los principios de confidencialidad, protección de datos personales y manejo de información institucional.', 'A', 'OD', 'Ante la petición simulada de un médico de conocer los resultados de otro paciente o los precios de un convenio ajeno, se niega y explica el motivo.'),
    ('VTA', 11, 'Identificación, comunicación y seguimiento de riesgos, quejas y oportunidades de mejora relacionadas con la atención y comercialización de los servicios.', 'A', 'RR', 'Registra de manera textual una queja recibida en visita y la entrega en el formato institucional.');
